INSERT INTO spell VALUES (514,'Reduce Person, Mass','mass reduce person','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 4','V, S, M','1 round','Close (25 ft. + 5 ft./2 levels)','One humanoid creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level (D)','Fortitude negates','Yes','Reduces several creatures.',NULL,'A pinch of powdered iron.',NULL,NULL,'\n      <p>This spell functions like <i>reduce person</i>, except that it affects multiple creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Reduce Person, Mass\" level=\"5\"><p><h5>Reduce Person, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One humanoid creature/level, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>reduce person</i>, except that it affects multiple creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (515,'Refuge','refuge','Conjuration','Teleportation',NULL,NULL,'Cleric 7, Sorcerer/Wizard 9','V, S, M','1 standard action','Touch','Object touched',NULL,NULL,'Permanent until discharged','None','No','Alters item to transport its possessor to you.',NULL,'The specially prepared object, whose construction requires gems worth 1,500 gp.',NULL,NULL,'\n      <p>You create powerful magic in some specially prepared object. This object contains the power to instantly transport its possessor across any distance within the same plane to your abode. Once the item is transmuted, you must give it willingly to a creature and at the same time inform it of a command word to be spoken when the item is used. To make use of the item, the subject speaks the command word at the same time that it rends or breaks the item (a standard action). When this is done, the individual and all objects it is wearing and carrying (to a maximum of the character\'s heavy load) are instantly transported to your abode. No other creatures are affected (aside from a familiar that is touching the subject).</p>\n      <p>You can alter the spell when casting it so that it transports you to within 10 feet of the possessor of the item when it is broken and the command word spoken. You will have a general idea of the location and situation of the item possessor at the time the <i>refuge</i> spell is discharged, but once you decide to alter the spell in this fashion, you have no choice whether or not to be transported.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Refuge\" level=\"5\"><p><h5>Refuge</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Teleportation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You create powerful magic in some specially prepared object. This object contains the power to instantly transport its possessor across any distance within the same plane to your abode. Once the item is transmuted, you must give it willingly to a creature and at the same time inform it of a command word to be spoken when the item is used. To make use of the item, the subject speaks the command word at the same time that it rends or breaks the item (a standard action). When this is done, the individual and all objects it is wearing and carrying (to a maximum of the character\'s heavy load) are instantly transported to your abode. No other creatures are affected (aside from a familiar that is touching the subject).</p><p>You can alter the spell when casting it so that it transports you to within 10 feet of the possessor of the item when it is broken and the command word spoken. You will have a general idea of the location and situation of the item possessor at the time the <i>refuge</i> spell is discharged, but once you decide to alter the spell in this fashion, you have no choice whether or not to be transported.</p><p><i>Material Component:</i> The specially prepared object, whose construction requires gems worth 1,500 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (516,'Regenerate','regenerate','Conjuration','Healing',NULL,NULL,'Cleric 7, Druid 9, Healing 7','V, S, DF','3 full rounds','Touch','Living creature touched',NULL,NULL,'Instantaneous','Fortitude negates (harmless)','Yes (harmless)','Subject\'s severed limbs grow back, cures 4d8 damage +1/level (max +35).',NULL,NULL,NULL,NULL,'\n      <p>The subject\'s severed body members (fingers, toes, hands, feet, arms, legs, tails, or even heads of multiheaded creatures), broken bones, and ruined organs grow back. After the spell is cast, the physical regeneration is complete in 1 round if the severed members are present and touching the creature. It takes 2d10 rounds otherwise.</p>\n      <p><i>Regenerate</i> also cures 4d8 points of damage +1 point per caster level (maximum +35), rids the subject of exhaustion and/or fatigue, and eliminates all nonlethal damage the subject has taken. It has no effect on nonliving creatures (including undead).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Regenerate\" level=\"5\"><p><h5>Regenerate</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Druid 9, Healing 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>3 full rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject\'s severed body members (fingers, toes, hands, feet, arms, legs, tails, or even heads of multiheaded creatures), broken bones, and ruined organs grow back. After the spell is cast, the physical regeneration is complete in 1 round if the severed members are present and touching the creature. It takes 2d10 rounds otherwise.</p><p><i>Regenerate</i> also cures 4d8 points of damage +1 point per caster level (maximum +35), rids the subject of exhaustion and/or fatigue, and eliminates all nonlethal damage the subject has taken. It has no effect on nonliving creatures (including undead).</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (517,'Reincarnate','reincarnate','Transmutation',NULL,NULL,NULL,'Druid 4','V, S, M, DF','10 minutes','Touch','Dead creature touched',NULL,NULL,'Instantaneous','None; see text','Yes (harmless)','Brings dead subject back in a random body.',NULL,'Rare oils and unguents worth a total of least 1,000 gp, spread over the remains.',NULL,NULL,'\n      <p>With this spell, you bring back a dead creature in another body, provided that its death occurred no more than one week before the casting of the spell and the subject\'s soul is free and willing to return. If the subject\'s soul is not willing to return, the spell does not work; therefore, a subject that wants to return receives no saving throw.</p>\n      <p>Since the dead creature is returning in a new body, all physical ills and afflictions are repaired. The condition of the remains is not a factor. So long as some small portion of the creature\'s body still exists, it can be reincarnated, but the portion receiving the spell must have been part of the creature\'s body at the time of death. The magic of the spell creates an entirely new young adult body for the soul to inhabit from the natural elements at hand. This process takes 1 hour to complete.  When the body is ready, the subject is reincarnated.</p>\n      <p>A reincarnated creature recalls the majority of its former life and form. It retains any class abilities, feats, or skill ranks it formerly possessed. Its class, base attack bonus, base save bonuses, and hit points are unchanged. Strength, Dexterity, and Constitution scores depend partly on the new body. First eliminate the subject\'s racial adjustments (since it is no longer of his previous race) and then apply the adjustments found below to its remaining ability scores. The subject\'s level (or Hit Dice) is reduced by 1. If the subject was 1st level, its new Constitution score is reduced by 2. (If this reduction would put its Con at 0 or lower, it can\'t be reincarnated). This level/HD loss or Constitution loss cannot be repaired by any means.</p>\n      <p>It\'s possible for the change in the subject\'s ability scores to make it difficult for it to pursue its previous character class. If this is the case, the subject is well advised to become a multiclass character.</p>\n      <p>For a humanoid creature, the new incarnation is determined using the following table. For nonhumanoid creatures, a similar table of creatures of the same type should be created.</p>\n      <p>A creature that has been turned into an undead creature or killed by a death effect can\'t be returned to life by this spell.  Constructs, elementals, outsiders, and undead creatures can\'t be reincarnated. The spell cannot bring back a creature who has died of old age.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>d%</b><br/></td>\n<td><b>Incarnation</b><br/></td>\n<td><b>Str</b><br/></td>\n<td><b>Dex</b><br/></td>\n<td><b>Con</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>01<br/></td>\n<td>Bugbear<br/></td>\n<td>+4<br/></td>\n<td>+2<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>02-13<br/></td>\n<td>Dwarf<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>14-25<br/></td>\n<td>Elf<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>26<br/></td>\n<td>Gnoll<br/></td>\n<td>+4<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>27-38<br/></td>\n<td>Gnome<br/></td>\n<td>-2<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>39-42<br/></td>\n<td>Goblin<br/></td>\n<td>-2<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>43-52<br/></td>\n<td>Half-elf<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>53-62<br/></td>\n<td>Half-orc<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>63-74<br/></td>\n<td>Halfling<br/></td>\n<td>-2<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>75-89<br/></td>\n<td>Human<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>90-93<br/></td>\n<td>Kobold<br/></td>\n<td>-4<br/></td>\n<td>+2<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>94<br/></td>\n<td>Lizardfolk<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>95-98<br/></td>\n<td>Orc<br/></td>\n<td>+4<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>99<br/></td>\n<td>Troglodyte<br/></td>\n<td>+0<br/></td>\n<td>-2<br/></td>\n<td>+4<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>100<br/></td>\n<td>Other<br/></td>\n<td>?<br/></td>\n<td>?<br/></td>\n<td>?<br/></td>\n\n</tr>\n</table>\n      <p>The reincarnated creature gains all abilities associated with its new form, including forms of movement and speeds, natural armor, natural attacks, extraordinary abilities, and the like, but it doesn\'t automatically speak the language of the new form.</p>\n      <p>A <i>wish</i> or a <i>miracle</i> spell can restore a reincarnated character to his or her original form.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Reincarnate\" level=\"5\"><p><h5>Reincarnate</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Dead creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>With this spell, you bring back a dead creature in another body, provided that its death occurred no more than one week before the casting of the spell and the subject\'s soul is free and willing to return. If the subject\'s soul is not willing to return, the spell does not work; therefore, a subject that wants to return receives no saving throw.</p><p>Since the dead creature is returning in a new body, all physical ills and afflictions are repaired. The condition of the remains is not a factor. So long as some small portion of the creature\'s body still exists, it can be reincarnated, but the portion receiving the spell must have been part of the creature\'s body at the time of death. The magic of the spell creates an entirely new young adult body for the soul to inhabit from the natural elements at hand. This process takes 1 hour to complete.  When the body is ready, the subject is reincarnated.</p><p>A reincarnated creature recalls the majority of its former life and form. It retains any class abilities, feats, or skill ranks it formerly possessed. Its class, base attack bonus, base save bonuses, and hit points are unchanged. Strength, Dexterity, and Constitution scores depend partly on the new body. First eliminate the subject\'s racial adjustments (since it is no longer of his previous race) and then apply the adjustments found below to its remaining ability scores. The subject\'s level (or Hit Dice) is reduced by 1. If the subject was 1st level, its new Constitution score is reduced by 2. (If this reduction would put its Con at 0 or lower, it can\'t be reincarnated). This level/HD loss or Constitution loss cannot be repaired by any means.</p><p>It\'s possible for the change in the subject\'s ability scores to make it difficult for it to pursue its previous character class. If this is the case, the subject is well advised to become a multiclass character.</p><p>For a humanoid creature, the new incarnation is determined using the following table. For nonhumanoid creatures, a similar table of creatures of the same type should be created.</p><p>A creature that has been turned into an undead creature or killed by a death effect can\'t be returned to life by this spell.  Constructs, elementals, outsiders, and undead creatures can\'t be reincarnated. The spell cannot bring back a creature who has died of old age.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>d%</b><br/></td>\n<td><b>Incarnation</b><br/></td>\n<td><b>Str</b><br/></td>\n<td><b>Dex</b><br/></td>\n<td><b>Con</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>01<br/></td>\n<td>Bugbear<br/></td>\n<td>+4<br/></td>\n<td>+2<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>02-13<br/></td>\n<td>Dwarf<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>14-25<br/></td>\n<td>Elf<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>26<br/></td>\n<td>Gnoll<br/></td>\n<td>+4<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>27-38<br/></td>\n<td>Gnome<br/></td>\n<td>-2<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>39-42<br/></td>\n<td>Goblin<br/></td>\n<td>-2<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>43-52<br/></td>\n<td>Half-elf<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>53-62<br/></td>\n<td>Half-orc<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>63-74<br/></td>\n<td>Halfling<br/></td>\n<td>-2<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>75-89<br/></td>\n<td>Human<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>90-93<br/></td>\n<td>Kobold<br/></td>\n<td>-4<br/></td>\n<td>+2<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>94<br/></td>\n<td>Lizardfolk<br/></td>\n<td>+2<br/></td>\n<td>+0<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>95-98<br/></td>\n<td>Orc<br/></td>\n<td>+4<br/></td>\n<td>+0<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>99<br/></td>\n<td>Troglodyte<br/></td>\n<td>+0<br/></td>\n<td>-2<br/></td>\n<td>+4<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>100<br/></td>\n<td>Other<br/></td>\n<td>?<br/></td>\n<td>?<br/></td>\n<td>?<br/></td>\n\n</tr>\n</table><p>The reincarnated creature gains all abilities associated with its new form, including forms of movement and speeds, natural armor, natural attacks, extraordinary abilities, and the like, but it doesn\'t automatically speak the language of the new form.</p><p>A <i>wish</i> or a <i>miracle</i> spell can restore a reincarnated character to his or her original form.</p><p><i>Material Component:</i> Rare oils and unguents worth a total of least 1,000 gp, spread over the remains.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (518,'Remove Blindness/Deafness','remove blindness/deafness','Conjuration','Healing',NULL,NULL,'Cleric 3, Paladin 3','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Fortitude negates (harmless)','Yes (harmless)','Cures normal or magical conditions.',NULL,NULL,NULL,NULL,'\n      <p><i>Remove blindness/deafness</i> cures blindness or deafness (your choice), whether the effect is normal or magical in nature. The spell does not restore ears or eyes that have been lost, but it repairs them if they are damaged.</p>\n      <p><i>Remove blindness/deafness</i> counters and dispels <i>blindness/deafness</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Remove Blindness/Deafness\" level=\"5\"><p><h5>Remove Blindness/Deafness</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Paladin 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Remove blindness/deafness</i> cures blindness or deafness (your choice), whether the effect is normal or magical in nature. The spell does not restore ears or eyes that have been lost, but it repairs them if they are damaged.</p><p><i>Remove blindness/deafness</i> counters and dispels <i>blindness/deafness</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (519,'Remove Curse','remove curse','Abjuration',NULL,NULL,NULL,'Bard 3, Cleric 3, Paladin 3, Sorcerer/Wizard 4','V, S','1 standard action','Touch','Creature or item touched',NULL,NULL,'Instantaneous','Will negates (harmless)','Yes (harmless)','Frees object or person from curse.',NULL,NULL,NULL,NULL,'\n      <p><i>Remove curse</i> instantaneously removes all curses on an object or a creature. <i>Remove curse</i> does not remove the curse from a cursed shield, weapon, or suit of armor, although the spell typically enables the creature afflicted with any such cursed item to remove and get rid of it. Certain special curses may not be countered by this spell or may be countered only by a caster of a certain level or higher.</p>\n      <p><i>Remove curse</i> counters and dispels <i>bestow curse</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Remove Curse\" level=\"5\"><p><h5>Remove Curse</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Cleric 3, Paladin 3, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature or item touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Remove curse</i> instantaneously removes all curses on an object or a creature. <i>Remove curse</i> does not remove the curse from a cursed shield, weapon, or suit of armor, although the spell typically enables the creature afflicted with any such cursed item to remove and get rid of it. Certain special curses may not be countered by this spell or may be countered only by a caster of a certain level or higher.</p><p><i>Remove curse</i> counters and dispels <i>bestow curse</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (520,'Remove Disease','remove disease','Conjuration','Healing',NULL,NULL,'Cleric 3, Druid 3, Ranger 3','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Fortitude negates (harmless)','Yes (harmless)','Cures all diseases affecting subject.',NULL,NULL,NULL,NULL,'\n      <p><i>Remove disease</i> cures all diseases that the subject is suffering from. The spell also kills parasites, including green slime and others. Certain special diseases may not be countered by this spell or may be countered only by a caster of a certain level or higher.</p>\n      <p><i>Note:</i> Since the spell\'s duration is instantaneous, it does not prevent reinfection after a new exposure to the same disease at a later date.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Remove Disease\" level=\"5\"><p><h5>Remove Disease</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Druid 3, Ranger 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Remove disease</i> cures all diseases that the subject is suffering from. The spell also kills parasites, including green slime and others. Certain special diseases may not be countered by this spell or may be countered only by a caster of a certain level or higher.</p><p><i>Note:</i> Since the spell\'s duration is instantaneous, it does not prevent reinfection after a new exposure to the same disease at a later date.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (521,'Remove Fear','remove fear','Abjuration',NULL,NULL,NULL,'Bard 1, Cleric 1','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature plus one additional creature per four levels, no two of which can be more than 30 ft. apart',NULL,NULL,'10 minutes; see text','Will negates (harmless)','Yes (harmless)','Suppresses fear or gives +4 on saves against fear for one subject + one per four levels.',NULL,NULL,NULL,NULL,'\n      <p>You instill courage in the subject, granting it a +4 morale bonus against <i>fear</i> effects for 10 minutes. If the subject is under the influence of a <i>fear</i> effect when receiving the spell, that effect is suppressed for the duration of the spell.</p>\n      <p><i>Remove fear</i> counters and dispels <i>cause fear</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Remove Fear\" level=\"5\"><p><h5>Remove Fear</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Cleric 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature plus one additional creature per four levels, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 minutes; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>You instill courage in the subject, granting it a +4 morale bonus against <i>fear</i> effects for 10 minutes. If the subject is under the influence of a <i>fear</i> effect when receiving the spell, that effect is suppressed for the duration of the spell.</p><p><i>Remove fear</i> counters and dispels <i>cause fear</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (522,'Remove Paralysis','remove paralysis','Conjuration','Healing',NULL,NULL,'Cleric 2, Paladin 2','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','Up to four creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will negates (harmless)','Yes (harmless)','Frees one or more creatures from paralysis or slow effect.',NULL,NULL,NULL,NULL,'\n      <p>You can free one or more creatures from the effects of any temporary paralysis or related magic, including a ghoul\'s touch or a <i>slow</i> spell. If the spell is cast on one creature, the paralysis is negated. If cast on two creatures, each receives another save with a +4 resistance bonus against the effect that afflicts it. If cast on three or four creatures, each receives another save with a +2 resistance bonus.</p>\n      <p>The spell does not restore ability scores reduced by penalties, damage, or drain.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Remove Paralysis\" level=\"5\"><p><h5>Remove Paralysis</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Paladin 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to four creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>You can free one or more creatures from the effects of any temporary paralysis or related magic, including a ghoul\'s touch or a <i>slow</i> spell. If the spell is cast on one creature, the paralysis is negated. If cast on two creatures, each receives another save with a +4 resistance bonus against the effect that afflicts it. If cast on three or four creatures, each receives another save with a +2 resistance bonus.</p><p>The spell does not restore ability scores reduced by penalties, damage, or drain.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (523,'Repel Metal or Stone','repel metal or stone','Abjuration',NULL,'Earth',NULL,'Druid 8','V, S','1 standard action','60 ft.',NULL,'60-ft. line from you',NULL,'1 round/level (D)','None','No','Pushes away metal and stone.',NULL,NULL,NULL,NULL,'\n      <p>Like <i>repel wood</i>,  this spell creates waves of invisible and intangible energy that roll forth from you. All metal or stone objects in the path of the spell are pushed away from you to the limit of the range. Fixed metal or stone objects larger than 3 inches in diameter and loose objects weighing more than 500 pounds are not affected. Anything else, including animated objects, small boulders, and creatures in metal armor, moves back. Fixed objects 3 inches in diameter or smaller bend or break, and the pieces move with the wave of energy. Objects affected by the spell are repelled at the rate of 40 feet per round.</p>\n      <p>Objects such as metal armor, swords, and the like are pushed back, dragging their bearers with them. Even magic items with metal components are repelled, although an <i>antimagic field</i> blocks the effects.</p>\n      <p>The waves of energy continue to sweep down the set path for the spell\'s duration. After you cast the spell, the path is set, and you can then do other things or go elsewhere without affecting the spell\'s power.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Repel Metal or Stone\" level=\"5\"><p><h5>Repel Metal or Stone</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>60-ft. line from you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Like <i>repel wood</i>,  this spell creates waves of invisible and intangible energy that roll forth from you. All metal or stone objects in the path of the spell are pushed away from you to the limit of the range. Fixed metal or stone objects larger than 3 inches in diameter and loose objects weighing more than 500 pounds are not affected. Anything else, including animated objects, small boulders, and creatures in metal armor, moves back. Fixed objects 3 inches in diameter or smaller bend or break, and the pieces move with the wave of energy. Objects affected by the spell are repelled at the rate of 40 feet per round.</p><p>Objects such as metal armor, swords, and the like are pushed back, dragging their bearers with them. Even magic items with metal components are repelled, although an <i>antimagic field</i> blocks the effects.</p><p>The waves of energy continue to sweep down the set path for the spell\'s duration. After you cast the spell, the path is set, and you can then do other things or go elsewhere without affecting the spell\'s power.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (524,'Repel Vermin','repel vermin','Abjuration',NULL,NULL,NULL,'Bard 4, Cleric 4, Druid 4, Ranger 3','V, S, DF','1 standard action','10 ft.',NULL,'10-ft. -radius emanation centered on you',NULL,'10 min./level (D)','None or Will negates; see text','Yes','Insects, spiders, and other vermin stay 10 ft. away.',NULL,NULL,NULL,NULL,'\n      <p>An invisible barrier holds back vermin. A vermin with Hit Dice of less than one-third your level cannot penetrate the barrier.</p>\n      <p>A vermin with Hit Dice of one-third your level or more can penetrate the barrier if it succeeds on a Will save. Even so, crossing the barrier deals the vermin 2d6 points of damage, and pressing against the barrier causes pain, which deters most vermin.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Repel Vermin\" level=\"5\"><p><h5>Repel Vermin</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Cleric 4, Druid 4, Ranger 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>10 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. -radius emanation centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>An invisible barrier holds back vermin. A vermin with Hit Dice of less than one-third your level cannot penetrate the barrier.</p><p>A vermin with Hit Dice of one-third your level or more can penetrate the barrier if it succeeds on a Will save. Even so, crossing the barrier deals the vermin 2d6 points of damage, and pressing against the barrier causes pain, which deters most vermin.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (525,'Repel Wood','repel wood','Transmutation',NULL,NULL,NULL,'Druid 6, Plant 6','V, S','1 standard action','60 ft.',NULL,'60-ft. line-shaped emanation from you',NULL,'1 min./level (D)','None','No','Pushes away wooden objects.',NULL,NULL,NULL,NULL,'\n      <p>Waves of energy roll forth from you, moving in the direction that you determine, causing all wooden objects in the path of the spell to be pushed away from you to the limit of the range. Wooden objects larger than 3 inches in diameter that are fixed firmly are not affected, but loose objects are. Objects 3 inches in diameter or smaller that are fixed in place splinter and break, and the pieces move with the wave of energy. Objects affected by the spell are repelled at the rate of 40 feet per round.</p>\n      <p>Objects such as wooden shields, spears, wooden weapon shafts and hafts, and arrows and bolts are pushed back, dragging those carrying them along. (A creature being dragged by an item it is carrying can let go. A creature being dragged by a shield can loose it as a move action and drop it as a free action.) If a spear is planted (set) to prevent this forced movement, it splinters. Even magic items with wooden sections are repelled, although an <i>antimagic field</i> blocks the effects.</p>\n      <p>The waves of energy continue to sweep down the set path for the spell\'s duration. After you cast the spell, the path is set, and you can then do other things or go elsewhere without affecting the spell\'s power.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Repel Wood\" level=\"5\"><p><h5>Repel Wood</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 6, Plant 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>60-ft. line-shaped emanation from you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Waves of energy roll forth from you, moving in the direction that you determine, causing all wooden objects in the path of the spell to be pushed away from you to the limit of the range. Wooden objects larger than 3 inches in diameter that are fixed firmly are not affected, but loose objects are. Objects 3 inches in diameter or smaller that are fixed in place splinter and break, and the pieces move with the wave of energy. Objects affected by the spell are repelled at the rate of 40 feet per round.</p><p>Objects such as wooden shields, spears, wooden weapon shafts and hafts, and arrows and bolts are pushed back, dragging those carrying them along. (A creature being dragged by an item it is carrying can let go. A creature being dragged by a shield can loose it as a move action and drop it as a free action.) If a spear is planted (set) to prevent this forced movement, it splinters. Even magic items with wooden sections are repelled, although an <i>antimagic field</i> blocks the effects.</p><p>The waves of energy continue to sweep down the set path for the spell\'s duration. After you cast the spell, the path is set, and you can then do other things or go elsewhere without affecting the spell\'s power.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (526,'Repulsion','repulsion','Abjuration',NULL,NULL,NULL,'Cleric 7, Protection 7, Sorcerer/Wizard 6','V, S, F/DF','1 standard action','Up to 10 ft./level',NULL,'Up to 10-ft. -radius/level emanation centered on you',NULL,'1 round/level (D)','Will negates','Yes','Creatures can\'t approach you.',NULL,NULL,NULL,NULL,'\n      <p>An invisible, mobile field surrounds you and prevents creatures from approaching you. You decide how big the field is at the time of casting (to the limit your level allows). Any creature within or entering the field must attempt a save. If it fails, it becomes unable to move toward you for the duration of the spell. Repelled creatures\' actions are not otherwise restricted.</p>\n      <p>They can fight other creatures and can cast spells and attack you with ranged weapons. If you move closer to an affected creature, nothing happens. (The creature is not forced back.) The creature is free to make melee attacks against you if you come within reach. If a repelled creature moves away from you and then tries to turn back toward you, it cannot move any closer if it is still within the spell\'s area.</p>\n      <p/>\n    ',NULL,'A pair of small iron bars attached to two small canine statuettes, one black and one white, the whole array worth 50 gp.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Repulsion\" level=\"5\"><p><h5>Repulsion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Protection 7, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Up to 10 ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Up to 10-ft. -radius/level emanation centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>An invisible, mobile field surrounds you and prevents creatures from approaching you. You decide how big the field is at the time of casting (to the limit your level allows). Any creature within or entering the field must attempt a save. If it fails, it becomes unable to move toward you for the duration of the spell. Repelled creatures\' actions are not otherwise restricted.</p><p>They can fight other creatures and can cast spells and attack you with ranged weapons. If you move closer to an affected creature, nothing happens. (The creature is not forced back.) The creature is free to make melee attacks against you if you come within reach. If a repelled creature moves away from you and then tries to turn back toward you, it cannot move any closer if it is still within the spell\'s area.</p><p><i>Arcane Focus:</i> A pair of small iron bars attached to two small canine statuettes, one black and one white, the whole array worth 50 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (527,'Resilient Sphere','resilient sphere','Evocation',NULL,'Force',NULL,'Sorcerer/Wizard 4','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'1-ft. -diameter/level sphere, centered around a creature','1 min./level (D)','Reflex negates','Yes','Force globe protects but traps one subject.',NULL,'A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.',NULL,NULL,'\n      <p>A globe of shimmering force encloses a creature, provided the creature is small enough to fit within the diameter of the sphere. The sphere contains its subject for the spell\'s duration. The sphere is not subject to damage of any sort except from a <i>rod of cancellation</i>, a rod <i>of negation</i>, a <i>disintegrate</i> spell, or a targeted <i>dispel magic</i> spell. These effects destroy the sphere without harm to the subject. Nothing can pass through the sphere, inside or out, though the subject can breathe normally.</p>\n      <p>The subject may struggle, but the sphere cannot be physically moved either by people outside it or by the struggles of those within.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Resilient Sphere\" level=\"5\"><p><h5>Resilient Sphere</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>1-ft. -diameter/level sphere, centered around a creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A globe of shimmering force encloses a creature, provided the creature is small enough to fit within the diameter of the sphere. The sphere contains its subject for the spell\'s duration. The sphere is not subject to damage of any sort except from a <i>rod of cancellation</i>, a rod <i>of negation</i>, a <i>disintegrate</i> spell, or a targeted <i>dispel magic</i> spell. These effects destroy the sphere without harm to the subject. Nothing can pass through the sphere, inside or out, though the subject can breathe normally.</p><p>The subject may struggle, but the sphere cannot be physically moved either by people outside it or by the struggles of those within.</p><p><i>Material Component:</i> A hemispherical piece of clear crystal and a matching hemispherical piece of gum arabic.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (528,'Resistance','resistance','Abjuration',NULL,NULL,NULL,'Bard 0, Cleric 0, Druid 0, Paladin 1, Sorcerer/Wizard 0','V, S, M/DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 minute','Will negates (harmless)','Yes (harmless)','Subject gains +1 on saving throws.',NULL,NULL,'A miniature cloak.',NULL,'\n      <p>You imbue the subject with magical energy that protects it from harm, granting it a +1 resistance bonus on saves.</p>\n      <p><i>Resistance</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Resistance\" level=\"5\"><p><h5>Resistance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0, Cleric 0, Druid 0, Paladin 1, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>You imbue the subject with magical energy that protects it from harm, granting it a +1 resistance bonus on saves.</p><p><i>Resistance</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Arcane Material Component:</i> A miniature cloak.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (529,'Resist Energy','resist energy','Abjuration',NULL,NULL,NULL,'Cleric 2, Druid 2, Fire 3, Paladin 2, Ranger 1, Sorcerer/Wizard 2','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'10 min./level','Fortitude negates (harmless)','Yes (harmless)','Ignores first 10 (or more) points of damage/attack from specified energy type.',NULL,NULL,NULL,NULL,'\n      <p>This abjuration grants a creature limited protection from damage of whichever one of five energy types you select: acid, cold, electricity, fire, or sonic. The subject gains energy resistance 10 against the energy type chosen, meaning that each time the creature is subjected to such damage (whether from a natural or magical source), that damage is reduced by 10 points before being applied to the creature\'s hit points. The value of the energy resistance granted increases to 20 points at 7th level and to a maximum of 30 points at 11th level. The spell protects the recipient\'s equipment as well.</p>\n      <p><i>Resist energy</i> absorbs only damage. The subject could still suffer unfortunate side effects.</p>\n      <p><i>Note: Resist energy</i> overlaps (and does not stack with) <i>protection from energy</i>. If a character is warded by <i>protection from energy</i> and <i>resist energy</i>,  the <i>protection</i> spell absorbs damage until its power is exhausted.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Resist Energy\" level=\"5\"><p><h5>Resist Energy</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Druid 2, Fire 3, Paladin 2, Ranger 1, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>This abjuration grants a creature limited protection from damage of whichever one of five energy types you select: acid, cold, electricity, fire, or sonic. The subject gains energy resistance 10 against the energy type chosen, meaning that each time the creature is subjected to such damage (whether from a natural or magical source), that damage is reduced by 10 points before being applied to the creature\'s hit points. The value of the energy resistance granted increases to 20 points at 7th level and to a maximum of 30 points at 11th level. The spell protects the recipient\'s equipment as well.</p><p><i>Resist energy</i> absorbs only damage. The subject could still suffer unfortunate side effects.</p><p><i>Note: Resist energy</i> overlaps (and does not stack with) <i>protection from energy</i>. If a character is warded by <i>protection from energy</i> and <i>resist energy</i>,  the <i>protection</i> spell absorbs damage until its power is exhausted.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (530,'Restoration','restoration','Conjuration','Healing',NULL,NULL,'Cleric 4, Paladin 4','V, S, M','3 rounds','Touch','Creature touched',NULL,NULL,'Instantaneous','Will negates (harmless)','Yes (harmless)','Restores level and ability score drains.',NULL,'Diamond dust worth 100 gp that is sprinkled over the target.',NULL,NULL,'\n      <p>This spell functions like <i>lesser restoration</i>,  except that it also dispels negative levels and restores one experience level to a creature who has had a level drained. The drained level is restored only if the time since the creature lost the level is equal to or less than one day per caster level. A character who has a level restored by r<i>estoration has</i> exactly the minimum number of experience points necessary to restore him or her to his or her previous level.</p>\n      <p><i>Restoration</i> cures all temporary ability damage, and it restores all points permanently drained from a single ability score (your choice if more than one is drained). It also eliminates any fatigue or exhaustion suffered by the target.</p>\n      <p><i>Restoration</i> does not restore levels or Constitution points lost due to death.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Restoration\" level=\"5\"><p><h5>Restoration</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 4, Paladin 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr></table><p>This spell functions like <i>lesser restoration</i>,  except that it also dispels negative levels and restores one experience level to a creature who has had a level drained. The drained level is restored only if the time since the creature lost the level is equal to or less than one day per caster level. A character who has a level restored by r<i>estoration has</i> exactly the minimum number of experience points necessary to restore him or her to his or her previous level.</p><p><i>Restoration</i> cures all temporary ability damage, and it restores all points permanently drained from a single ability score (your choice if more than one is drained). It also eliminates any fatigue or exhaustion suffered by the target.</p><p><i>Restoration</i> does not restore levels or Constitution points lost due to death.</p><p><i>Material Component:</i> Diamond dust worth 100 gp that is sprinkled over the target.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (531,'Restoration, Greater','greater restoration','Conjuration','Healing',NULL,NULL,'Cleric 7','V, S, XP','10 minutes','Touch','Creature touched',NULL,NULL,'Instantaneous','Will negates (harmless)','Yes (harmless)','As restoration, plus restores all levels and ability scores.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>lesser restoration</i>,  except that it dispels all negative levels afflicting the healed creature. This effect also reverses level drains by a force or creature, restoring the creature to the highest level it had previously attained. The drained levels are restored only if the time since the creature lost the level is no more than one week per caster level.</p>\n      <p><i>Greater restoration</i> also dispels all magical effects penalizing the creature\'s abilities, cures all temporary ability damage, and restores all points permanently drained from all ability scores. It also eliminates fatigue and exhaustion, and removes all forms of insanity, <i>confusion</i>,  and similar mental effects. <i>Greater restoration</i> does not restore levels or Constitution points lost due to death.</p>\n      <p/>\n    ','500 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Restoration, Greater\" level=\"5\"><p><h5>Restoration, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr></table><p>This spell functions like <i>lesser restoration</i>,  except that it dispels all negative levels afflicting the healed creature. This effect also reverses level drains by a force or creature, restoring the creature to the highest level it had previously attained. The drained levels are restored only if the time since the creature lost the level is no more than one week per caster level.</p><p><i>Greater restoration</i> also dispels all magical effects penalizing the creature\'s abilities, cures all temporary ability damage, and restores all points permanently drained from all ability scores. It also eliminates fatigue and exhaustion, and removes all forms of insanity, <i>confusion</i>,  and similar mental effects. <i>Greater restoration</i> does not restore levels or Constitution points lost due to death.</p><p><i>XP Cost:</i> 500 XP.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (532,'Restoration, Lesser','lesser restoration','Conjuration','Healing',NULL,NULL,'Cleric 2, Druid 2, Paladin 1','V, S','3 rounds','Touch','Creature touched',NULL,NULL,'Instantaneous','Will negates (harmless)','Yes (harmless)','Dispels magical ability penalty or repairs 1d4 ability damage.',NULL,NULL,NULL,NULL,'\n      <p><i>Lesser restoration</i> dispels any magical effects reducing one of the subject\'s ability scores or cures 1d4 points of temporary ability damage to one of the subject\'s ability scores. It also eliminates any fatigue suffered by the character, and improves an exhausted condition to fatigued. It does not restore permanent ability drain.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Restoration, Lesser\" level=\"5\"><p><h5>Restoration, Lesser</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Druid 2, Paladin 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>3 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Lesser restoration</i> dispels any magical effects reducing one of the subject\'s ability scores or cures 1d4 points of temporary ability damage to one of the subject\'s ability scores. It also eliminates any fatigue suffered by the character, and improves an exhausted condition to fatigued. It does not restore permanent ability drain.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (533,'Resurrection','resurrection','Conjuration','Healing',NULL,NULL,'Cleric 7','V, S, M, DF','10 minutes','Touch','Dead creature touched',NULL,NULL,'Instantaneous','None; see text','Yes (harmless)','Fully restore dead subject.',NULL,'A sprinkle of holy water and diamonds worth a total of at least 10,000 gp.',NULL,NULL,'\n      <p>This spell functions like <i>raise dead</i>,  except that you are able to restore life and complete strength to any deceased creature.</p>\n      <p>The condition of the remains is not a factor. So long as some small portion of the creature\'s body still exists, it can be resurrected, but the portion receiving the spell must have been part of the creature\'s body at the time of death. (The remains of a creature hit by a <i>disintegrate</i> spell count as a small portion of its body.) The creature can have been dead no longer than 10 years per caster level.</p>\n      <p>Upon completion of the spell, the creature is immediately restored to full hit points, vigor, and health, with no loss of prepared spells. However, the subject loses one level, or 2 points of Constitution if the subject was 1st level. (If this reduction would bring its Con to 0 or lower, it can\'t be resurrected). This level loss or Constitution loss cannot be repaired by any means.</p>\n      <p>You can resurrect someone killed by a death effect or someone who has been turned into an undead creature and then destroyed. You cannot resurrect someone who has died of old age. Constructs, elementals, outsiders, and undead creatures can\'t be resurrected.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Resurrection\" level=\"5\"><p><h5>Resurrection</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr></table><p>This spell functions like <i>raise dead</i>,  except that you are able to restore life and complete strength to any deceased creature.</p><p>The condition of the remains is not a factor. So long as some small portion of the creature\'s body still exists, it can be resurrected, but the portion receiving the spell must have been part of the creature\'s body at the time of death. (The remains of a creature hit by a <i>disintegrate</i> spell count as a small portion of its body.) The creature can have been dead no longer than 10 years per caster level.</p><p>Upon completion of the spell, the creature is immediately restored to full hit points, vigor, and health, with no loss of prepared spells. However, the subject loses one level, or 2 points of Constitution if the subject was 1st level. (If this reduction would bring its Con to 0 or lower, it can\'t be resurrected). This level loss or Constitution loss cannot be repaired by any means.</p><p>You can resurrect someone killed by a death effect or someone who has been turned into an undead creature and then destroyed. You cannot resurrect someone who has died of old age. Constructs, elementals, outsiders, and undead creatures can\'t be resurrected.</p><p><i>Material Component:</i> A sprinkle of holy water and diamonds worth a total of at least 10,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (534,'Reverse Gravity','reverse gravity','Transmutation',NULL,NULL,NULL,'Druid 8, Sorcerer/Wizard 7','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Up to one 10-ft. cube per two levels (S)',NULL,'1 round/level (D)','None; see text','No','Objects and creatures fall upward.',NULL,NULL,'A lodestone and iron filings.',NULL,'\n      <p>This spell reverses gravity in an area, causing all unattached objects and creatures within that area to fall upward and reach the top of the area in 1 round. If some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it in the same manner as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, until the spell ends. At the end of the spell duration, affected objects and creatures fall downward.</p>\n      <p>Provided it has something to hold onto, a creature caught in the area can attempt a Reflex save to secure itself when the spell strikes. Creatures who can fly or levitate can keep themselves from falling.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Reverse Gravity\" level=\"5\"><p><h5>Reverse Gravity</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 8, Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Up to one 10-ft. cube per two levels (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell reverses gravity in an area, causing all unattached objects and creatures within that area to fall upward and reach the top of the area in 1 round. If some solid object (such as a ceiling) is encountered in this fall, falling objects and creatures strike it in the same manner as they would during a normal downward fall. If an object or creature reaches the top of the area without striking anything, it remains there, oscillating slightly, until the spell ends. At the end of the spell duration, affected objects and creatures fall downward.</p><p>Provided it has something to hold onto, a creature caught in the area can attempt a Reflex save to secure itself when the spell strikes. Creatures who can fly or levitate can keep themselves from falling.</p><p><i>Arcane Material Component:</i> A lodestone and iron filings.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (535,'Righteous Might','righteous might','Transmutation',NULL,NULL,NULL,'Cleric 5, Strength 5','V, S, DF','1 standard action','Personal','You',NULL,NULL,'1 round/level (D)',NULL,NULL,'Your size increases, and you gain combat bonuses.',NULL,NULL,NULL,NULL,'\n      <p>Your height immediately doubles, and your weight increases by a factor of eight. This increase changes your size category to the next larger one, and you gain a +8 size bonus to Strength and a +4 size bonus to Constitution. You gain a +4 enhancement bonus to your natural armor. You gain damage reduction 5/evil (if you normally channel positive energy) or damage reduction 5/good (if you normally channel negative energy). At 12th level this damage reduction becomes 10/evil or 10/good, and at 15th level it becomes 15/evil or 15/good (the maximum). Your size modifier for AC and attacks changes as appropriate to your new size category. This spell doesn\'t change your speed.  Determine space and reach as appropriate to your new size.</p>\n      <p>If insufficient room is available for the desired growth, you attain the maximum possible size and may make a Strength check (using your increased Strength) to burst any enclosures in the process. If you fail, you are constrained without harm by the materials enclosing you- the spell cannot crush you by increasing your size.</p>\n      <p>All equipment you wear or carry is similarly enlarged by the spell. Melee and projectile weapons deal more damage. Other magical properties are not affected by this spell. Any enlarged item that leaves your possession (including a projectile or thrown weapon) instantly returns to its normal size. This means that thrown weapons deal their normal damage (projectiles deal damage based on the size of the weapon that fired them).</p>\n      <p>Multiple magical effects that increase size do not stack.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Righteous Might\" level=\"5\"><p><h5>Righteous Might</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Strength 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr></table><p>Your height immediately doubles, and your weight increases by a factor of eight. This increase changes your size category to the next larger one, and you gain a +8 size bonus to Strength and a +4 size bonus to Constitution. You gain a +4 enhancement bonus to your natural armor. You gain damage reduction 5/evil (if you normally channel positive energy) or damage reduction 5/good (if you normally channel negative energy). At 12th level this damage reduction becomes 10/evil or 10/good, and at 15th level it becomes 15/evil or 15/good (the maximum). Your size modifier for AC and attacks changes as appropriate to your new size category. This spell doesn\'t change your speed.  Determine space and reach as appropriate to your new size.</p><p>If insufficient room is available for the desired growth, you attain the maximum possible size and may make a Strength check (using your increased Strength) to burst any enclosures in the process. If you fail, you are constrained without harm by the materials enclosing you- the spell cannot crush you by increasing your size.</p><p>All equipment you wear or carry is similarly enlarged by the spell. Melee and projectile weapons deal more damage. Other magical properties are not affected by this spell. Any enlarged item that leaves your possession (including a projectile or thrown weapon) instantly returns to its normal size. This means that thrown weapons deal their normal damage (projectiles deal damage based on the size of the weapon that fired them).</p><p>Multiple magical effects that increase size do not stack.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (536,'Rope Trick','rope trick','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 2','V, S, M','1 standard action','Touch','One touched piece of rope from 5 ft. to 30 ft. long',NULL,NULL,'1 hour/level (D)','None','No','As many as eight creatures hide in extradimensional space.',NULL,'Powdered corn extract and a twisted loop of parchment.',NULL,NULL,'\n      <p>When this spell is cast upon a piece of rope from 5 to 30 feet long, one end of the rope rises into the air until the whole rope hangs perpendicular to the ground, as if affixed at the upper end. The upper end is, in fact, fastened to an extradimensional space that is outside the multiverse of extradimensional spaces (\'planes\'). Creatures in the extradimensional space are hidden, beyond the reach of spells (including divinations), unless those spells work across planes. The space holds as many as eight creatures (of any size). Creatures in the space can pull the rope up into the space, making the rope \'disappear.\' In that case, the rope counts as one of the eight creatures that can fit in the space. The rope can support up to 16,000 pounds. A weight greater than that can pull the rope free.</p>\n      <p>Spells cannot be cast across the extradimensional interface, nor can area effects cross it. Those in the extradimensional space can see out of it as if a 3-foot-by- 5-foot window were centered on the rope. The window is present on the Material Plane, but it\'s invisible, and even creatures that can see the window can\'t see through it. Anything inside the extradimensional space drops out when the spell ends. The rope can be climbed by only one person at a time. The <i>rope trick</i> spell enables climbers to reach a normal place if they do not climb all the way to the extradimensional space.</p>\n      <p><i>Note:</i> It is hazardous to create an extradimensional space within an existing extradimensional space or to take an extradimensional space into an existing one.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Rope Trick\" level=\"5\"><p><h5>Rope Trick</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One touched piece of rope from 5 ft. to 30 ft. long<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>When this spell is cast upon a piece of rope from 5 to 30 feet long, one end of the rope rises into the air until the whole rope hangs perpendicular to the ground, as if affixed at the upper end. The upper end is, in fact, fastened to an extradimensional space that is outside the multiverse of extradimensional spaces (\'planes\'). Creatures in the extradimensional space are hidden, beyond the reach of spells (including divinations), unless those spells work across planes. The space holds as many as eight creatures (of any size). Creatures in the space can pull the rope up into the space, making the rope \'disappear.\' In that case, the rope counts as one of the eight creatures that can fit in the space. The rope can support up to 16,000 pounds. A weight greater than that can pull the rope free.</p><p>Spells cannot be cast across the extradimensional interface, nor can area effects cross it. Those in the extradimensional space can see out of it as if a 3-foot-by- 5-foot window were centered on the rope. The window is present on the Material Plane, but it\'s invisible, and even creatures that can see the window can\'t see through it. Anything inside the extradimensional space drops out when the spell ends. The rope can be climbed by only one person at a time. The <i>rope trick</i> spell enables climbers to reach a normal place if they do not climb all the way to the extradimensional space.</p><p><i>Note:</i> It is hazardous to create an extradimensional space within an existing extradimensional space or to take an extradimensional space into an existing one.</p><p><i>Material Component:</i> Powdered corn extract and a twisted loop of parchment.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (537,'Rusting Grasp','rusting grasp','Transmutation',NULL,NULL,NULL,'Druid 4','V, S, DF','1 standard action','Touch','One nonmagical ferrous object (or the volume of the object within 3 ft. of the touched point) or one ferrous creature',NULL,NULL,'See text','None','No','Your touch corrodes iron and alloys.',NULL,NULL,NULL,NULL,'\n      <p>Any iron or iron alloy item you touch becomes instantaneously rusted, pitted, and worthless, effectively destroyed. If the item is so large that it cannot fit within a 3-foot radius a 3-foot-radius volume of the metal is rusted and destroyed. Magic items made of metal are immune to this spell.</p>\n      <p>You may employ <i>Rusting grasp</i> in combat with a successful melee touch attack. <i>Rusting grasp</i> used in this way instantaneously destroys 1d6 points of Armor Class gained from metal armor (to the maximum amount of protection the armor offered) through corrosion.</p>\n      <p>Weapons in use by an opponent targeted by the spell are more difficult to grasp. You must succeed on a melee touch attack against the weapon. A metal weapon that is hit is destroyed.</p>\n      <p><i>Note:</i> Striking at an opponent\'s weapon provokes an attack of opportunity. Also, you must touch the weapon and not the other way around.</p>\n      <p>Against a ferrous creature, <i>Rusting grasp</i> instantaneously deals 3d6 points of damage +1 per caster level (maximum +15) per successful attack. The spell lasts for 1 round per level, and you can make one melee touch attack per round.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Rusting Grasp\" level=\"5\"><p><h5>Rusting Grasp</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One nonmagical ferrous object (or the volume of the object within 3 ft. of the touched point) or one ferrous creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Any iron or iron alloy item you touch becomes instantaneously rusted, pitted, and worthless, effectively destroyed. If the item is so large that it cannot fit within a 3-foot radius a 3-foot-radius volume of the metal is rusted and destroyed. Magic items made of metal are immune to this spell.</p><p>You may employ <i>Rusting grasp</i> in combat with a successful melee touch attack. <i>Rusting grasp</i> used in this way instantaneously destroys 1d6 points of Armor Class gained from metal armor (to the maximum amount of protection the armor offered) through corrosion.</p><p>Weapons in use by an opponent targeted by the spell are more difficult to grasp. You must succeed on a melee touch attack against the weapon. A metal weapon that is hit is destroyed.</p><p><i>Note:</i> Striking at an opponent\'s weapon provokes an attack of opportunity. Also, you must touch the weapon and not the other way around.</p><p>Against a ferrous creature, <i>Rusting grasp</i> instantaneously deals 3d6 points of damage +1 per caster level (maximum +15) per successful attack. The spell lasts for 1 round per level, and you can make one melee touch attack per round.</p><p/>\n</div>\n    ','SRD 3.5 SpellsP-R');
INSERT INTO spell VALUES (538,'Sanctuary','sanctuary','Abjuration',NULL,NULL,NULL,'Cleric 1, Protection 1','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 round/level','Will negates','No','Opponents can\'t attack you, and you can\'t attack.',NULL,NULL,NULL,NULL,'\n      <p>Any opponent attempting to strike or otherwise directly attack the warded creature, even with a targeted spell, must attempt a Will save. If the save succeeds, the opponent can attack normally and is unaffected by that casting of the spell. If the save fails, the opponent can\'t follow through with the attack, that part of its action is lost, and it can\'t directly attack the warded creature for the duration of the spell. Those not attempting to attack the subject remain unaffected. This spell does not prevent the warded creature from being attacked or affected by area or effect spells. The subject cannot attack without breaking the spell but may use nonattack spells or otherwise act.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sanctuary\" level=\"5\"><p><h5>Sanctuary</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1, Protection 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Any opponent attempting to strike or otherwise directly attack the warded creature, even with a targeted spell, must attempt a Will save. If the save succeeds, the opponent can attack normally and is unaffected by that casting of the spell. If the save fails, the opponent can\'t follow through with the attack, that part of its action is lost, and it can\'t directly attack the warded creature for the duration of the spell. Those not attempting to attack the subject remain unaffected. This spell does not prevent the warded creature from being attacked or affected by area or effect spells. The subject cannot attack without breaking the spell but may use nonattack spells or otherwise act.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (539,'Scare','scare','Necromancy',NULL,'Fear, Mind-Affecting',NULL,'Bard 2, Sorcerer/Wizard 2','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)','One living creature per three levels, no two of which can be more than 30 ft. apart',NULL,NULL,'1 round/level or 1 round; see text for cause fear','Will partial','Yes','Panics creatures of less than 6 HD.',NULL,'A bit of bone from an undead skeleton, zombie, ghoul, ghast, or mummy.',NULL,NULL,'\n      <p>This spell functions like <i>cause fear</i>,  except that it causes all targeted creatures of less than 6 HD to become frightened.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Scare\" level=\"5\"><p><h5>Scare</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Fear, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One living creature per three levels, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level or 1 round; see text for cause fear<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell functions like <i>cause fear</i>,  except that it causes all targeted creatures of less than 6 HD to become frightened.</p><p><i>Material Component:</i> A bit of bone from an undead skeleton, zombie, ghoul, ghast, or mummy.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (540,'Scintillating Pattern','scintillating pattern','Illusion','Pattern','Mind-Affecting',NULL,'Sorcerer/Wizard 8','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Colorful lights in a 20-ft. -radius spread','Concentration + 2 rounds','None','Yes','Twisting colors confuse, stun, or render unconscious.',NULL,'A small crystal prism.',NULL,NULL,'\n      <p>A twisting pattern of discordant, coruscating colors weaves through the air, affecting creatures within it. The spell affects a total number of Hit Dice of creatures equal to your caster level (maximum 20). Creatures with the fewest HD are affected first; and, among creatures with equal HD, those who are closest to the spell\'s point of origin are affected first. Hit Dice that are not sufficient to affect a creature are wasted. The spell affects each subject according to its Hit Dice.</p>\n      <p><i>6 or less:</i> Unconscious for 1d4 rounds, then stunned for 1d4 rounds, and then <i>confused</i> for 1d4 rounds. (Treat an unconscious result as stunned for nonliving creatures.)</p>\n      <p><i>7 to 12:</i> Stunned for 1d4 rounds, then <i>confused</i> for 1d4 rounds.</p>\n      <p><i>13 or more: Confused</i> for 1d4 rounds.</p>\n      <p>Sightless creatures are not affected by <i>scintillating pattern</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Scintillating Pattern\" level=\"5\"><p><h5>Scintillating Pattern</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Pattern) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Colorful lights in a 20-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration + 2 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A twisting pattern of discordant, coruscating colors weaves through the air, affecting creatures within it. The spell affects a total number of Hit Dice of creatures equal to your caster level (maximum 20). Creatures with the fewest HD are affected first; and, among creatures with equal HD, those who are closest to the spell\'s point of origin are affected first. Hit Dice that are not sufficient to affect a creature are wasted. The spell affects each subject according to its Hit Dice.</p><p><i>6 or less:</i> Unconscious for 1d4 rounds, then stunned for 1d4 rounds, and then <i>confused</i> for 1d4 rounds. (Treat an unconscious result as stunned for nonliving creatures.)</p><p><i>7 to 12:</i> Stunned for 1d4 rounds, then <i>confused</i> for 1d4 rounds.</p><p><i>13 or more: Confused</i> for 1d4 rounds.</p><p>Sightless creatures are not affected by <i>scintillating pattern</i>.</p><p><i>Material Component:</i> A small crystal prism.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (541,'Scorching Ray','scorching ray','Evocation',NULL,'Fire',NULL,'Sorcerer/Wizard 2','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more rays','Instantaneous','None','Yes','Ranged touch attack deals 4d6 fire damage, +1 ray/four levels (max 3).',NULL,NULL,NULL,NULL,'\n      <p>You blast your enemies with fiery rays. You may fire one ray, plus one additional ray for every four levels beyond 3rd (to a maximum of three rays at 11th level). Each ray requires a ranged touch attack to hit and deals 4d6 points of fire damage.</p>\n      <p>The rays may be fired at the same or different targets, but all bolts must be aimed at targets within 30 feet of each other and fired simultaneously.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Scorching Ray\" level=\"5\"><p><h5>Scorching Ray</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One or more rays<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You blast your enemies with fiery rays. You may fire one ray, plus one additional ray for every four levels beyond 3rd (to a maximum of three rays at 11th level). Each ray requires a ranged touch attack to hit and deals 4d6 points of fire damage.</p><p>The rays may be fired at the same or different targets, but all bolts must be aimed at targets within 30 feet of each other and fired simultaneously.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (542,'Screen','screen','Illusion','Glamer',NULL,NULL,'Sorcerer/Wizard 8, Trickery 7','V, S','10 minutes','Close (25 ft. + 5 ft./2 levels)',NULL,'30-ft. cube/level (S)',NULL,'24 hours','None or Will disbelief (if interacted with); see text','No','Illusion hides area from vision, scrying.',NULL,NULL,NULL,NULL,'\n      <p>This spell combines several elements to create a powerful protection from scrying and direct observation. When casting the spell, you dictate what will and will not be observed in the spell\'s area. The illusion created must be stated in general terms. Once the conditions are set, they cannot be changed.</p>\n      <p>Attempts to scry the area automatically detect the image stated by you with no save allowed. Sight and sound are appropriate to the illusion created.</p>\n      <p>Direct observation may allow a save (as per a normal illusion), if there is cause to disbelieve what is seen. Even entering the area does not cancel the illusion or necessarily allow a save, assuming that hidden beings take care to stay out of the way of those affected by the illusion.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Screen\" level=\"5\"><p><h5>Screen</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8, Trickery 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>30-ft. cube/level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will disbelief (if interacted with); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell combines several elements to create a powerful protection from scrying and direct observation. When casting the spell, you dictate what will and will not be observed in the spell\'s area. The illusion created must be stated in general terms. Once the conditions are set, they cannot be changed.</p><p>Attempts to scry the area automatically detect the image stated by you with no save allowed. Sight and sound are appropriate to the illusion created.</p><p>Direct observation may allow a save (as per a normal illusion), if there is cause to disbelieve what is seen. Even entering the area does not cancel the illusion or necessarily allow a save, assuming that hidden beings take care to stay out of the way of those affected by the illusion.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (543,'Scrying','scrying','Divination','Scrying',NULL,NULL,'Bard 3, Cleric 5, Druid 4, Sorcerer/Wizard 4','V, S, M/DF, F','1 hour','See text',NULL,NULL,'Magical sensor','1 min./level','Will negates','Yes','Spies on subject from a distance.',NULL,NULL,'The eye of a hawk, an eagle, or a roc, plus nitric acid, copper, and zinc.',NULL,'\n      <p>You can see and hear some creature, which may be at any distance. If the subject succeeds on a Will save, the scrying attempt simply fails. The difficulty of the save depends on how well you know the subject and what sort of physical connection (if any) you have to that creature. Furthermore, if the subject is on another plane, it gets a +5 bonus on its Will save.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Knowledge</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>None<sup><b>1</b></sup><br/></td>\n<td>+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Secondhand (you have heard of the subject)<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Firsthand (you have met the subject)<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Familiar (you know the subject well)<br/></td>\n<td>-5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 You must have some sort of connection to a creature you have no knowledge of.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Connection</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Likeness or picture<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Possession or garment<br/></td>\n<td>-4<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Body part, lock of hair, bit of nail, etc.<br/></td>\n<td>-10<br/></td>\n\n</tr>\n</table>\n      <p>If the save fails, you can see and hear the subject and the subject\'s immediate surroundings (approximately 10 feet in all directions of the subject). If the subject moves, the sensor follows at a speed of up to 150 feet.</p>\n      <p>As with all divination (scrying) spells, the sensor has your full visual acuity, including any magical effects. In addition, the following spells have a 5% chance per caster level of operating through the sensor: <i>detect chaos</i>, <i>detect evil</i>, <i>detect good</i>, <i>detect law</i>, <i>detect magic</i>, and <i>message</i>.</p>\n      <p>If the save succeeds, you can\'t attempt to scry on that subject again for at least 24 hours.</p>\n      <p/>\n    ',NULL,NULL,'A mirror of finely wrought and highly polished silver costing not less than 1,000 gp. The mirror must be at least 2 feet by 4 feet.',NULL,'A mirror of finely wrought and highly polished silver costing not less than 1,000 gp. The mirror must be at least 2 feet by 4 feet.','A mirror of finely wrought and highly polished silver costing not less than 1,000 gp. The mirror must be at least 2 feet by 4 feet.','A holy water font costing not less than 100 gp.','A natural pool of water.','\n      <div topic=\"Scrying\" level=\"5\"><p><h5>Scrying</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination (Scrying)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Cleric 5, Druid 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 hour<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Magical sensor<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You can see and hear some creature, which may be at any distance. If the subject succeeds on a Will save, the scrying attempt simply fails. The difficulty of the save depends on how well you know the subject and what sort of physical connection (if any) you have to that creature. Furthermore, if the subject is on another plane, it gets a +5 bonus on its Will save.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Knowledge</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>None<sup><b>1</b></sup><br/></td>\n<td>+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Secondhand (you have heard of the subject)<br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Firsthand (you have met the subject)<br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Familiar (you know the subject well)<br/></td>\n<td>-5<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"2\">\n<td colspan=\"2\">1 You must have some sort of connection to a creature you have no knowledge of.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Connection</b><br/></td>\n<td><b>Will Save Modifier</b><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Likeness or picture<br/></td>\n<td>-2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Possession or garment<br/></td>\n<td>-4<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Body part, lock of hair, bit of nail, etc.<br/></td>\n<td>-10<br/></td>\n\n</tr>\n</table><p>If the save fails, you can see and hear the subject and the subject\'s immediate surroundings (approximately 10 feet in all directions of the subject). If the subject moves, the sensor follows at a speed of up to 150 feet.</p><p>As with all divination (scrying) spells, the sensor has your full visual acuity, including any magical effects. In addition, the following spells have a 5% chance per caster level of operating through the sensor: <i>detect chaos</i>, <i>detect evil</i>, <i>detect good</i>, <i>detect law</i>, <i>detect magic</i>, and <i>message</i>.</p><p>If the save succeeds, you can\'t attempt to scry on that subject again for at least 24 hours.</p><p><i>Arcane Material Component:</i> The eye of a hawk, an eagle, or a roc, plus nitric acid, copper, and zinc.</p><p><i>Wizard</i>,  <i>Sorcerer</i>,  <i>or Bard Focus:</i> A mirror of finely wrought and highly polished silver costing not less than 1,000 gp. The mirror must be at least 2 feet by 4 feet.</p><p><i>Cleric Focus:</i> A holy water font costing not less than 100 gp.</p><p><i>Druid Focus:</i> A natural pool of water.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (544,'Scrying, Greater','greater scrying','Divination','Scrying',NULL,NULL,'Bard 6, Cleric 7, Druid 7, Sorcerer/Wizard 7','V, S','1 standard action','See text',NULL,NULL,'Magical sensor','1 hour/level','Will negates','Yes','As scrying, but faster and longer.',NULL,NULL,'The eye of a hawk, an eagle, or a roc, plus nitric acid, copper, and zinc.',NULL,'\n      <p>This spell functions like <i>scrying</i>, except as noted above. Additionally, all of the following spells function reliably through the sensor: <i>detect chaos</i>, <i>detect evil</i>, <i>detect good</i>, <i>detect law</i>, <i>detect magic</i>, <i>message</i>, <i>read magic</i>, and <i>tongues</i>.</p>\n      <p/>\n    ',NULL,NULL,'A mirror of finely wrought and highly polished silver costing not less than 1,000 gp. The mirror must be at least 2 feet by 4 feet.',NULL,'A mirror of finely wrought and highly polished silver costing not less than 1,000 gp. The mirror must be at least 2 feet by 4 feet.','A mirror of finely wrought and highly polished silver costing not less than 1,000 gp. The mirror must be at least 2 feet by 4 feet.','A holy water font costing not less than 100 gp.','A natural pool of water.','\n      <div topic=\"Scrying, Greater\" level=\"5\"><p><h5>Scrying, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination (Scrying)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Cleric 7, Druid 7, Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr></table><p>This spell functions like <i>scrying</i>, except as noted above. Additionally, all of the following spells function reliably through the sensor: <i>detect chaos</i>, <i>detect evil</i>, <i>detect good</i>, <i>detect law</i>, <i>detect magic</i>, <i>message</i>, <i>read magic</i>, and <i>tongues</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (545,'Sculpt Sound','sculpt sound','Transmutation',NULL,NULL,NULL,'Bard 3','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature or object/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 hour/level (D)','Will negates (object)','Yes (object)','Creates new sounds or changes existing ones.',NULL,NULL,NULL,NULL,'\n      <p>You change the sounds that creatures or objects make. You can create sounds where none exist, deaden sounds, or transform sounds into other sounds. All affected creatures or objects must be transmuted in the same way. Once the transmutation is made, you cannot change it.</p>\n      <p>You can change the qualities of sounds but cannot create words with which you are unfamiliar yourself.</p>\n      <p>A spellcaster whose voice is changed dramatically is unable to cast spells with verbal components.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sculpt Sound\" level=\"5\"><p><h5>Sculpt Sound</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature or object/level, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>You change the sounds that creatures or objects make. You can create sounds where none exist, deaden sounds, or transform sounds into other sounds. All affected creatures or objects must be transmuted in the same way. Once the transmutation is made, you cannot change it.</p><p>You can change the qualities of sounds but cannot create words with which you are unfamiliar yourself.</p><p>A spellcaster whose voice is changed dramatically is unable to cast spells with verbal components.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (546,'Searing Light','searing light','Evocation',NULL,NULL,NULL,'Cleric 3, Sun 3','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Ray','Instantaneous','None','Yes','Ray deals 1d8/two levels, more against undead.',NULL,NULL,NULL,NULL,'\n      <p>Focusing divine power like a ray of the sun, you project a blast of light from your open palm. You must succeed on a ranged touch attack to strike your target. A creature struck by this ray of light takes 1d8 points of damage per two caster levels (maximum 5d8). An undead creature takes 1d6 points of damage per caster level (maximum 10d6), and an undead creature particularly vulnerable to bright light takes 1d8 points of damage per caster level (maximum 10d8). A construct or inanimate object takes only 1d6 points of damage per two caster levels (maximum 5d6).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Searing Light\" level=\"5\"><p><h5>Searing Light</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Sun 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Ray<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Focusing divine power like a ray of the sun, you project a blast of light from your open palm. You must succeed on a ranged touch attack to strike your target. A creature struck by this ray of light takes 1d8 points of damage per two caster levels (maximum 5d8). An undead creature takes 1d6 points of damage per caster level (maximum 10d6), and an undead creature particularly vulnerable to bright light takes 1d8 points of damage per caster level (maximum 10d8). A construct or inanimate object takes only 1d6 points of damage per two caster levels (maximum 5d6).</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (547,'Secret Chest','secret chest','Conjuration','Summoning',NULL,NULL,'Sorcerer/Wizard 5','V, S, F','10 minutes','See text','One chest and up to 1 cu. ft. of goods/caster level',NULL,NULL,'Sixty days or until discharged','None','No','Hides expensive chest on Ethereal Plane; you retrieve it at will.',NULL,NULL,NULL,'The chest and its replica.','\n      <p>You hide a chest on the Ethereal Plane for as long as sixty days and can retrieve it at will. The chest can contain up to 1 cubic foot of material per caster level (regardless of the chest\'s actual size, which is about 3 feet by 2 feet by 2 feet). If any living creatures are in the chest, there is a 75% chance that the spell simply fails. Once the chest is hidden, you can retrieve it by concentrating (a standard action), and it appears next to you.</p>\n      <p>The chest must be exceptionally well crafted and expensive, constructed for you by master crafters. The cost of such a chest is never less than 5,000 gp. Once it is constructed, you must make a tiny replica (of the same materials and perfect in every detail), so that the miniature of the chest appears to be a perfect copy. (The replica costs 50 gp.) You can have but one pair of these chests at any given time-even a <i>wish</i> spell does not allow more. The chests are nonmagical and can be fitted with locks, wards, and so on, just as any normal chest can be.</p>\n      <p>To hide the chest, you cast the spell while touching both the chest and the replica. The chest vanishes into the Ethereal Plane. You need the replica to recall the chest. After sixty days, there is a cumulative chance of 5% per day that the chest is irretrievably lost. If the miniature of the chest is lost or destroyed, there is no way, not even with a <i>wish</i> spell, that the large chest can be summoned back, although an extraplanar expedition might be mounted to find it.</p>\n      <p>Living things in the chest eat, sleep, and age normally, and they die if they run out of food, air, water, or whatever they need to survive.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Secret Chest\" level=\"5\"><p><h5>Secret Chest</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One chest and up to 1 cu. ft. of goods/caster level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Sixty days or until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You hide a chest on the Ethereal Plane for as long as sixty days and can retrieve it at will. The chest can contain up to 1 cubic foot of material per caster level (regardless of the chest\'s actual size, which is about 3 feet by 2 feet by 2 feet). If any living creatures are in the chest, there is a 75% chance that the spell simply fails. Once the chest is hidden, you can retrieve it by concentrating (a standard action), and it appears next to you.</p><p>The chest must be exceptionally well crafted and expensive, constructed for you by master crafters. The cost of such a chest is never less than 5,000 gp. Once it is constructed, you must make a tiny replica (of the same materials and perfect in every detail), so that the miniature of the chest appears to be a perfect copy. (The replica costs 50 gp.) You can have but one pair of these chests at any given time-even a <i>wish</i> spell does not allow more. The chests are nonmagical and can be fitted with locks, wards, and so on, just as any normal chest can be.</p><p>To hide the chest, you cast the spell while touching both the chest and the replica. The chest vanishes into the Ethereal Plane. You need the replica to recall the chest. After sixty days, there is a cumulative chance of 5% per day that the chest is irretrievably lost. If the miniature of the chest is lost or destroyed, there is no way, not even with a <i>wish</i> spell, that the large chest can be summoned back, although an extraplanar expedition might be mounted to find it.</p><p>Living things in the chest eat, sleep, and age normally, and they die if they run out of food, air, water, or whatever they need to survive.</p><p><i>Focus:</i> The chest and its replica.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (548,'Secret Page','secret page','Transmutation',NULL,NULL,NULL,'Bard 3, Sorcerer/Wizard 3','V, S, M','10 minutes','Touch','Page touched, up to 3 sq. ft. in size',NULL,NULL,'Permanent','None','No','Changes one page to hide its real content.',NULL,'Powdered herring scales and will-o\'-wisp essence.',NULL,NULL,'\n      <p>S<i>ecret page</i> alters the contents of a page so that they appear to be something entirely different. The text of a spell can be changed to show even another spell. <i>Explosive runes</i> or <i>Sepia snake sigil</i> can be cast upon the <i>secret page</i>.</p>\n      <p>A <i>comprehend languages</i> spell alone cannot reveal a <i>secret page</i>\'s contents. You are able to reveal the original contents by speaking a special word. You can then peruse the actual page, and return it to its <i>secret page</i> form at will. You can also remove the spell by double repetition of the special word. A <i>detect magic</i> spell reveals dim magic on the page in question but does not reveal its true contents. T<i>rue seeing</i> reveals the presence of the hidden material but does not reveal the contents unless cast in combination with <i>comprehend languages</i>. A <i>secret page</i> spell can be dispelled, and the hidden writings can be destroyed by means of an <i>erase</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Secret Page\" level=\"5\"><p><h5>Secret Page</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Page touched, up to 3 sq. ft. in size<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>S<i>ecret page</i> alters the contents of a page so that they appear to be something entirely different. The text of a spell can be changed to show even another spell. <i>Explosive runes</i> or <i>Sepia snake sigil</i> can be cast upon the <i>secret page</i>.</p><p>A <i>comprehend languages</i> spell alone cannot reveal a <i>secret page</i>\'s contents. You are able to reveal the original contents by speaking a special word. You can then peruse the actual page, and return it to its <i>secret page</i> form at will. You can also remove the spell by double repetition of the special word. A <i>detect magic</i> spell reveals dim magic on the page in question but does not reveal its true contents. T<i>rue seeing</i> reveals the presence of the hidden material but does not reveal the contents unless cast in combination with <i>comprehend languages</i>. A <i>secret page</i> spell can be dispelled, and the hidden writings can be destroyed by means of an <i>erase</i> spell.</p><p><i>Material Component:</i> Powdered herring scales and will-o\'-wisp essence.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (549,'Secure Shelter','secure shelter','Conjuration','Creation',NULL,NULL,'Bard 4, Sorcerer/Wizard 4','V, S, M, F; see text','10 minutes','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'20-ft. -square structure','2 hours/level (D)','None','No','Creates sturdy cottage.',NULL,'A square chip of stone, crushed lime, a few grains of sand, a sprinkling of water, and several splinters of wood. These must be augmented by the components of the unseen servant spell (string and a bit of wood) if this benefit is to be included.',NULL,'The focus of the alarm spell (silver wire and a tiny bell) if this benefit is to be included.','\n      <p>You conjure a sturdy cottage or lodge made of material that is common in the area where the spell is cast. The floor is level, clean, and dry. In all respects the lodging resembles a normal cottage, with a sturdy door, two shuttered windows, and a small fireplace.</p>\n      <p>The shelter has no heating or cooling source (other than natural insulation qualities). Therefore, it must be heated as a normal dwelling, and extreme heat adversely affects it and its occupants. The dwelling does, however, provide considerable security otherwise-it is as strong as a normal stone building, regardless of its material composition. The dwelling resists flames and fire as if it were stone. It is impervious to normal missiles (but not the sort cast by siege engines or giants).</p>\n      <p>The door, shutters, and even chimney are secure against intrusion, the former two being <i>arcane locked</i> and the latter secured by an iron grate at the top and a narrow flue. In addition, these three areas are protected by an <i>alarm</i> spell. Finally, an <i>unseen servant</i> is conjured to provide service to you for the duration of the shelter.</p>\n      <p>The <i>secure shelter</i> contains rude furnishings -eight bunks, a trestle table, eight stools, and a writing desk.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Secure Shelter\" level=\"5\"><p><h5>Secure Shelter</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, F; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>20-ft. -square structure<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You conjure a sturdy cottage or lodge made of material that is common in the area where the spell is cast. The floor is level, clean, and dry. In all respects the lodging resembles a normal cottage, with a sturdy door, two shuttered windows, and a small fireplace.</p><p>The shelter has no heating or cooling source (other than natural insulation qualities). Therefore, it must be heated as a normal dwelling, and extreme heat adversely affects it and its occupants. The dwelling does, however, provide considerable security otherwise-it is as strong as a normal stone building, regardless of its material composition. The dwelling resists flames and fire as if it were stone. It is impervious to normal missiles (but not the sort cast by siege engines or giants).</p><p>The door, shutters, and even chimney are secure against intrusion, the former two being <i>arcane locked</i> and the latter secured by an iron grate at the top and a narrow flue. In addition, these three areas are protected by an <i>alarm</i> spell. Finally, an <i>unseen servant</i> is conjured to provide service to you for the duration of the shelter.</p><p>The <i>secure shelter</i> contains rude furnishings -eight bunks, a trestle table, eight stools, and a writing desk.</p><p><i>Material Component:</i> A square chip of stone, crushed lime, a few grains of sand, a sprinkling of water, and several splinters of wood. These must be augmented by the components of the <i>unseen servant</i> spell (string and a bit of wood) if this benefit is to be included.</p><p><i>Focus:</i> The focus of the <i>alarm</i> spell (silver wire and a tiny bell) if this benefit is to be included.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (550,'See Invisibility','see invisibility','Divination',NULL,NULL,NULL,'Bard 3, Sorcerer/Wizard 2','V, S, M','1 standard action','Personal','You',NULL,NULL,'10 min./level (D)',NULL,NULL,'Reveals invisible creatures or objects.',NULL,'A pinch of talc and a small sprinkling of powdered silver.',NULL,NULL,'\n      <p>You can see any objects or beings that are invisible within your range of vision, as well as any that are ethereal, as if they were normally visible. Such creatures are visible to you as translucent shapes, allowing you easily to discern the difference between visible, invisible, and ethereal creatures.</p>\n      <p>The spell does not reveal the method used to obtain invisibility. It does not reveal illusions or enable you to see through opaque objects. It does not reveal creatures who are simply hiding, concealed, or otherwise hard to see.</p>\n      <p><i>See invisibility</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"See Invisibility\" level=\"5\"><p><h5>See Invisibility</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr></table><p>You can see any objects or beings that are invisible within your range of vision, as well as any that are ethereal, as if they were normally visible. Such creatures are visible to you as translucent shapes, allowing you easily to discern the difference between visible, invisible, and ethereal creatures.</p><p>The spell does not reveal the method used to obtain invisibility. It does not reveal illusions or enable you to see through opaque objects. It does not reveal creatures who are simply hiding, concealed, or otherwise hard to see.</p><p><i>See invisibility</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Material Component:</i> A pinch of talc and a small sprinkling of powdered silver.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (551,'Seeming','seeming','Illusion','Glamer',NULL,NULL,'Bard 5, Sorcerer/Wizard 5','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature per two levels, no two of which can be more than 30 ft. apart',NULL,NULL,'12 hours (D)','Will negates or Will disbelief (if interacted with)','Yes or No; see text','Changes appearance of one person per two levels.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>disguise self</i>,  except that you can change the appearance of other people as well. Affected creatures resume their normal appearances if slain.</p>\n      <p>Unwilling targets can negate the spell\'s effect on them by making Will saves or with spell resistance.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Seeming\" level=\"5\"><p><h5>Seeming</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature per two levels, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>12 hours (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates or Will disbelief (if interacted with)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes or No; see text<br/></td></tr></table><p>This spell functions like <i>disguise self</i>,  except that you can change the appearance of other people as well. Affected creatures resume their normal appearances if slain.</p><p>Unwilling targets can negate the spell\'s effect on them by making Will saves or with spell resistance.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (552,'Sending','sending','Evocation',NULL,NULL,NULL,'Cleric 4, Sorcerer/Wizard 5','V, S, M/DF','10 minutes','See text','One creature',NULL,NULL,'1 round; see text','None','No','Delivers short message anywhere, instantly.',NULL,NULL,'A short piece of fine copper wire.',NULL,'\n      <p>You contact a particular creature with which you are familiar and send a short message of twenty-five words or less to the subject. The subject recognizes you if it knows you. It can answer in like manner immediately. A creature with an Intelligence score as low as 1 can understand the <i>sending</i>,  though the subject\'s ability to react is limited as normal by its Intelligence score. Even if the <i>sending</i> is received, the subject is not obligated to act upon it in any manner.</p>\n      <p>If the creature in question is not on the same plane of existence as you are, there is a 5% chance that the <i>sending</i> does not arrive. (Local conditions on other planes may worsen this chance considerably.)</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sending\" level=\"5\"><p><h5>Sending</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 4, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You contact a particular creature with which you are familiar and send a short message of twenty-five words or less to the subject. The subject recognizes you if it knows you. It can answer in like manner immediately. A creature with an Intelligence score as low as 1 can understand the <i>sending</i>,  though the subject\'s ability to react is limited as normal by its Intelligence score. Even if the <i>sending</i> is received, the subject is not obligated to act upon it in any manner.</p><p>If the creature in question is not on the same plane of existence as you are, there is a 5% chance that the <i>sending</i> does not arrive. (Local conditions on other planes may worsen this chance considerably.)</p><p><i>Arcane Material Component:</i> A short piece of fine copper wire.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (553,'Sepia Snake Sigil','sepia snake sigil','Conjuration','Creation','Force',NULL,'Bard 3, Sorcerer/Wizard 3','V, S, M','10 minutes','Touch','One touched book or written work',NULL,NULL,'Permanent or until discharged; until released or 1d4 days + one day/level; see text','Reflex negates','No','Creates text symbol that immobilizes reader.',NULL,'500 gp worth of powdered amber, a scale from any snake, and a pinch of mushroom spores.',NULL,NULL,'\n      <p>When you cast <i>sepia snake sigil</i>,  a small symbol appears in the text of one written work such as a book, scroll, or map. The text containing the symbol must be at least twenty-five words long. When anyone reads the text containing the symbol, the <i>sepia snake</i> springs into being and strikes the reader, provided there is line of effect between the symbol and the reader.</p>\n      <p>Simply seeing the enspelled text is not sufficient to trigger the spell; the subject must deliberately read it. The target is entitled to a save to evade the snake\'s strike. If it succeeds, the <i>sepia snake</i> dissipates in a flash of brown light accompanied by a puff of dun-colored smoke and a loud noise. If the target fails its save, it is engulfed in a shimmering amber field of force and immobilized until released, either at your command or when 1d4 days + one day per caster level have elapsed.</p>\n      <p>While trapped in the amber field of force, the subject does not age, breathe, grow hungry, sleep, or regain spells. It is preserved in a state of suspended animation, unaware of its surroundings. It can be damaged by outside forces (and perhaps even killed), since the field provides no protection against physical injury. However, a dying subject does not lose hit points or become stable until the spell ends.</p>\n      <p>The hidden sigil cannot be detected by normal observation, and <i>detect magic</i> reveals only that the entire text is magical.</p>\n      <p>A <i>dispel magic</i> can remove the sigil. An <i>erase</i> spell destroys the entire page of text.</p>\n      <p><i>Sepia snake sigil</i> can be cast in combination with other spells that hide or garble text, such as <i>secret page</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sepia Snake Sigil\" level=\"5\"><p><h5>Sepia Snake Sigil</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One touched book or written work<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent or until discharged; until released or 1d4 days + one day/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>When you cast <i>sepia snake sigil</i>,  a small symbol appears in the text of one written work such as a book, scroll, or map. The text containing the symbol must be at least twenty-five words long. When anyone reads the text containing the symbol, the <i>sepia snake</i> springs into being and strikes the reader, provided there is line of effect between the symbol and the reader.</p><p>Simply seeing the enspelled text is not sufficient to trigger the spell; the subject must deliberately read it. The target is entitled to a save to evade the snake\'s strike. If it succeeds, the <i>sepia snake</i> dissipates in a flash of brown light accompanied by a puff of dun-colored smoke and a loud noise. If the target fails its save, it is engulfed in a shimmering amber field of force and immobilized until released, either at your command or when 1d4 days + one day per caster level have elapsed.</p><p>While trapped in the amber field of force, the subject does not age, breathe, grow hungry, sleep, or regain spells. It is preserved in a state of suspended animation, unaware of its surroundings. It can be damaged by outside forces (and perhaps even killed), since the field provides no protection against physical injury. However, a dying subject does not lose hit points or become stable until the spell ends.</p><p>The hidden sigil cannot be detected by normal observation, and <i>detect magic</i> reveals only that the entire text is magical.</p><p>A <i>dispel magic</i> can remove the sigil. An <i>erase</i> spell destroys the entire page of text.</p><p><i>Sepia snake sigil</i> can be cast in combination with other spells that hide or garble text, such as <i>secret page</i>.</p><p><i>Material Component:</i> 500 gp worth of powdered amber, a scale from any snake, and a pinch of mushroom spores.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (554,'Sequester','sequester','Abjuration',NULL,NULL,NULL,'Sorcerer/Wizard 7','V, S, M','1 standard action','Touch','One willing creature or object (up to a 2-ft. cube/level) touched',NULL,NULL,'One day/level (D)','None or Will negates (object)','No or Yes (object)','Subject is invisible to sight and scrying; renders creature comatose.',NULL,'A basilisk eyelash, gum arabic, and a dram of whitewash.',NULL,NULL,'\n      <p>When cast, this spell not only prevents divination spells from working to detect or locate the creature or object affected by <i>sequester</i>,  it also renders the affected creature or object invisible to any form of sight or seeing (as the <i>invisibility</i> spell). The spell does not prevent the subject from being discovered through tactile means or through the use of devices. Creatures affected by <i>sequester</i> become comatose and are effectively in a state of suspended animation until the spell wears off or is dispelled.</p>\n      <p><i>Note:</i> The Will save prevents an attended or magical object from being <i>sequestered</i>. There is no save to see the <i>sequestered</i> creature or object or to detect it with a divination spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sequester\" level=\"5\"><p><h5>Sequester</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One willing creature or object (up to a 2-ft. cube/level) touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No or Yes (object)<br/></td></tr></table><p>When cast, this spell not only prevents divination spells from working to detect or locate the creature or object affected by <i>sequester</i>,  it also renders the affected creature or object invisible to any form of sight or seeing (as the <i>invisibility</i> spell). The spell does not prevent the subject from being discovered through tactile means or through the use of devices. Creatures affected by <i>sequester</i> become comatose and are effectively in a state of suspended animation until the spell wears off or is dispelled.</p><p><i>Note:</i> The Will save prevents an attended or magical object from being <i>sequestered</i>. There is no save to see the <i>sequestered</i> creature or object or to detect it with a divination spell.</p><p><i>Material Component:</i> A basilisk eyelash, gum arabic, and a dram of whitewash.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (555,'Shades','shades','Illusion','Shadow',NULL,NULL,'Sorcerer/Wizard 9','V, S','1 standard action','See text',NULL,NULL,'See text','See text','Will disbelief (if interacted with); varies; see text','Yes; see text','As shadow conjuration, but up to 8th level and 80% real.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>shadow conjuration</i>,  except that it mimics sorcerer and wizard conjuration spells of 8th level or lower. The illusory conjurations created deal four-fifths (80%) damage to nonbelievers, and nondamaging effects are 80% likely to work against nonbelievers.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shades\" level=\"5\"><p><h5>Shades</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Shadow)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9<br/></td></tr></table><p>This spell functions like <i>shadow conjuration</i>,  except that it mimics sorcerer and wizard conjuration spells of 8th level or lower. The illusory conjurations created deal four-fifths (80%) damage to nonbelievers, and nondamaging effects are 80% likely to work against nonbelievers.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (556,'Shadow Conjuration','shadow conjuration','Illusion','Shadow',NULL,NULL,'Bard 4, Sorcerer/Wizard 4','V, S','1 standard action','See text',NULL,NULL,'See text','See text','Will disbelief (if interacted with); varies; see text','Yes; see text','Mimics conjuration below 4th level, but only 20% real.',NULL,NULL,NULL,NULL,'\n      <p>You use material from the Plane of Shadow to shape quasi-real illusions of one or more creatures, objects, or forces. <i>Shadow conjuration</i> can mimic any sorcerer or wizard conjuration (summoning) or conjuration (creation) spell of 3rd level or lower.</p>\n      <p><i>Shadow conjurations</i> are actually one-fifth (20%) as strong as the real things, though creatures who believe the <i>Shadow conjurations</i> to be real are affected by them at full strength.</p>\n      <p>Any creature that interacts with the conjured object, force, or creature can make a Will save to recognize its true nature.</p>\n      <p>Spells that deal damage have normal effects unless the affected creature succeeds on a Will save. Each disbelieving creature takes only one-fifth (20%) damage from the attack. If the disbelieved attack has a special effect other than damage, that effect is only 20% likely to occur. Regardless of the result of the save to disbelieve, an affected creature is also allowed any save that the spell being simulated allows, but the save DC is set according to <i>shadow conjuration</i>\'s level (4th) rather than the spell\'s normal level. In addition, any effect created by <i>Shadow conjuration</i> allows spell resistance, even if the spell it is simulating does not. Shadow objects or substances have normal effects except against those who disbelieve them.</p>\n      <p>Against disbelievers, they are 20% likely to work.</p>\n      <p>A shadow creature has one-fifth the hit points of a normal creature of its kind (regardless of whether it\'s recognized as shadowy). It deals normal damage and has all normal abilities and weaknesses. Against a creature that recognizes it as a shadow creature, however, the shadow creature\'s damage is one-fifth (20%) normal, and all special abilities that do not deal lethal damage are only 20% likely to work. (Roll for each use and each affected character separately.) Furthermore, the shadow creature\'s AC bonuses are one-fifth as large.</p>\n      <p>A creature that succeeds on its save sees the <i>Shadow conjurations</i> as transparent images superimposed on vague, shadowy forms.</p>\n      <p>Objects automatically succeed on their Will saves against this spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shadow Conjuration\" level=\"5\"><p><h5>Shadow Conjuration</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Shadow)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will disbelief (if interacted with); varies; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes; see text<br/></td></tr></table><p>You use material from the Plane of Shadow to shape quasi-real illusions of one or more creatures, objects, or forces. <i>Shadow conjuration</i> can mimic any sorcerer or wizard conjuration (summoning) or conjuration (creation) spell of 3rd level or lower.</p><p><i>Shadow conjurations</i> are actually one-fifth (20%) as strong as the real things, though creatures who believe the <i>Shadow conjurations</i> to be real are affected by them at full strength.</p><p>Any creature that interacts with the conjured object, force, or creature can make a Will save to recognize its true nature.</p><p>Spells that deal damage have normal effects unless the affected creature succeeds on a Will save. Each disbelieving creature takes only one-fifth (20%) damage from the attack. If the disbelieved attack has a special effect other than damage, that effect is only 20% likely to occur. Regardless of the result of the save to disbelieve, an affected creature is also allowed any save that the spell being simulated allows, but the save DC is set according to <i>shadow conjuration</i>\'s level (4th) rather than the spell\'s normal level. In addition, any effect created by <i>Shadow conjuration</i> allows spell resistance, even if the spell it is simulating does not. Shadow objects or substances have normal effects except against those who disbelieve them.</p><p>Against disbelievers, they are 20% likely to work.</p><p>A shadow creature has one-fifth the hit points of a normal creature of its kind (regardless of whether it\'s recognized as shadowy). It deals normal damage and has all normal abilities and weaknesses. Against a creature that recognizes it as a shadow creature, however, the shadow creature\'s damage is one-fifth (20%) normal, and all special abilities that do not deal lethal damage are only 20% likely to work. (Roll for each use and each affected character separately.) Furthermore, the shadow creature\'s AC bonuses are one-fifth as large.</p><p>A creature that succeeds on its save sees the <i>Shadow conjurations</i> as transparent images superimposed on vague, shadowy forms.</p><p>Objects automatically succeed on their Will saves against this spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (557,'Shadow Conjuration, Greater','greater shadow conjuration','Illusion','Shadow',NULL,NULL,'Sorcerer/Wizard 7','V, S','1 standard action','See text',NULL,NULL,'See text','See text','Will disbelief (if interacted with); varies; see text','Yes; see text','As shadow conjuration, but up to 6th level and 60% real.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>shadow conjuration</i>,  except that it can duplicate any sorcerer or wizard conjuration (summoning) or conjuration (creation) spell of 6th level or lower. The illusory conjurations created deal three-fifths (60%) damage to nonbelievers, and nondamaging effects are 60% likely to work against nonbelievers.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shadow Conjuration, Greater\" level=\"5\"><p><h5>Shadow Conjuration, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Shadow)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr></table><p>This spell functions like <i>shadow conjuration</i>,  except that it can duplicate any sorcerer or wizard conjuration (summoning) or conjuration (creation) spell of 6th level or lower. The illusory conjurations created deal three-fifths (60%) damage to nonbelievers, and nondamaging effects are 60% likely to work against nonbelievers.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (558,'Shadow Evocation','shadow evocation','Illusion','Shadow',NULL,NULL,'Bard 5, Sorcerer/Wizard 5','V, S','1 standard action','See text',NULL,NULL,'See text','See text','Will disbelief (if interacted with)','Yes','Mimics evocation below 5th level, but only 20% real.',NULL,NULL,NULL,NULL,'\n      <p>You tap energy from the Plane of Shadow to cast a quasi-real, illusory version of a sorcerer or wizard evocation spell of 4th level or lower. (For a spell with more than one level, use the best one applicable to you.)</p>\n      <p>Spells that deal damage have normal effects unless an affected creature succeeds on a Will save. Each disbelieving creature takes only one-fifth damage from the attack. If the disbelieved attack has a special effect other than damage, that effect is one-fifth as strong (if applicable) or only 20% likely to occur. If recognized as a <i>shadow evocation</i>,  a damaging spell deals only one-fifth (20%) damage. Regardless of the result of the save to disbelieve, an affected creature is also allowed any save (or spell resistance) that the spell being simulated allows, but the save DC is set according to <i>shadow evocation\'</i>s level (5th) rather than the spell\'s normal level.</p>\n      <p>Nondamaging effects have normal effects except against those who disbelieve them. Against disbelievers, they have no effect.</p>\n      <p>Objects automatically succeed on their Will saves against this spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shadow Evocation\" level=\"5\"><p><h5>Shadow Evocation</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Shadow)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will disbelief (if interacted with)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You tap energy from the Plane of Shadow to cast a quasi-real, illusory version of a sorcerer or wizard evocation spell of 4th level or lower. (For a spell with more than one level, use the best one applicable to you.)</p><p>Spells that deal damage have normal effects unless an affected creature succeeds on a Will save. Each disbelieving creature takes only one-fifth damage from the attack. If the disbelieved attack has a special effect other than damage, that effect is one-fifth as strong (if applicable) or only 20% likely to occur. If recognized as a <i>shadow evocation</i>,  a damaging spell deals only one-fifth (20%) damage. Regardless of the result of the save to disbelieve, an affected creature is also allowed any save (or spell resistance) that the spell being simulated allows, but the save DC is set according to <i>shadow evocation\'</i>s level (5th) rather than the spell\'s normal level.</p><p>Nondamaging effects have normal effects except against those who disbelieve them. Against disbelievers, they have no effect.</p><p>Objects automatically succeed on their Will saves against this spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (559,'Shadow Evocation, Greater','greater shadow evocation','Illusion','Shadow',NULL,NULL,'Sorcerer/Wizard 8','V, S','1 standard action','See text',NULL,NULL,'See text','See text','Will disbelief (if interacted with)','Yes','As shadow evocation, but up to 7th level and 60% real.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>shadow evocation</i>,  except that it enables you to create partially real, illusory versions of sorcerer or wizard evocation spells of 7th level or lower. If recognized as a <i>greater shadow evocation</i>, a damaging spell deals only three-fifths (60%) damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shadow Evocation, Greater\" level=\"5\"><p><h5>Shadow Evocation, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Shadow)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr></table><p>This spell functions like <i>shadow evocation</i>,  except that it enables you to create partially real, illusory versions of sorcerer or wizard evocation spells of 7th level or lower. If recognized as a <i>greater shadow evocation</i>, a damaging spell deals only three-fifths (60%) damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (560,'Shadow Walk','shadow walk','Illusion','Shadow',NULL,NULL,'Bard 5, Sorcerer/Wizard 6','V, S','1 standard action','Touch','Up to one touched creature/level',NULL,NULL,'1 hour/level (D)','Will negates','Yes','Step into shadow to travel rapidly.',NULL,NULL,NULL,NULL,'\n      <p>To use the <i>Shadow walk</i> spell, you must be in an area of shadowy illumination. You and any creature you touch are then transported along a coiling path of shadowstuff to the edge of the Material Plane where it borders the Plane of Shadow. The effect is largely illusory, but the path is quasi-real. You can take more than one creature along with you (subject to your level limit), but all must be touching each other.</p>\n      <p>In the region of shadow, you move at a rate of 50 miles per hour, moving normally on the borders of the Plane of Shadow but much more rapidly relative to the Material Plane. Thus, you can use this spell to travel rapidly by stepping onto the Plane of Shadow, moving the desired distance, and then stepping back onto the Material Plane.</p>\n      <p>Because of the blurring of reality between the Plane of Shadow and the Material Plane, you can\'t make out details of the terrain or areas you pass over during transit, nor can you predict perfectly where your travel will end. It\'s impossible to judge distances accurately, making the spell virtually useless for scouting or spying. Furthermore, when the spell effect ends, you are shunted 1d10x100 feet in a random horizontal direction from your desired endpoint. If this would place you within a solid object, you are shunted 1d10x1,000 feet in the same direction. If this would still place you within a solid object, you (and any creatures with you) are shunted to the nearest empty space available, but the strain of this activity renders each creature fatigued (no save).</p>\n      <p><i>Shadow walk</i> can also be used to travel to other planes that border on the Plane of Shadow, but this usage requires the transit of the Plane of Shadow to arrive at a border with another plane of reality. The transit of the Plane of Shadow requires 1d4 hours.</p>\n      <p>Any creatures touched by you when <i>Shadow walk</i> is cast also make the transition to the borders of the Plane of Shadow.</p>\n      <p>They may opt to follow you, wander off through the plane, or stumble back into the Material Plane (50% chance for either of the latter results if they are lost or abandoned by you). Creatures unwilling to accompany you into the Plane of Shadow receive a Will saving throw, negating the effect if successful.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shadow Walk\" level=\"5\"><p><h5>Shadow Walk</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Shadow)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to one touched creature/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>To use the <i>Shadow walk</i> spell, you must be in an area of shadowy illumination. You and any creature you touch are then transported along a coiling path of shadowstuff to the edge of the Material Plane where it borders the Plane of Shadow. The effect is largely illusory, but the path is quasi-real. You can take more than one creature along with you (subject to your level limit), but all must be touching each other.</p><p>In the region of shadow, you move at a rate of 50 miles per hour, moving normally on the borders of the Plane of Shadow but much more rapidly relative to the Material Plane. Thus, you can use this spell to travel rapidly by stepping onto the Plane of Shadow, moving the desired distance, and then stepping back onto the Material Plane.</p><p>Because of the blurring of reality between the Plane of Shadow and the Material Plane, you can\'t make out details of the terrain or areas you pass over during transit, nor can you predict perfectly where your travel will end. It\'s impossible to judge distances accurately, making the spell virtually useless for scouting or spying. Furthermore, when the spell effect ends, you are shunted 1d10x100 feet in a random horizontal direction from your desired endpoint. If this would place you within a solid object, you are shunted 1d10x1,000 feet in the same direction. If this would still place you within a solid object, you (and any creatures with you) are shunted to the nearest empty space available, but the strain of this activity renders each creature fatigued (no save).</p><p><i>Shadow walk</i> can also be used to travel to other planes that border on the Plane of Shadow, but this usage requires the transit of the Plane of Shadow to arrive at a border with another plane of reality. The transit of the Plane of Shadow requires 1d4 hours.</p><p>Any creatures touched by you when <i>Shadow walk</i> is cast also make the transition to the borders of the Plane of Shadow.</p><p>They may opt to follow you, wander off through the plane, or stumble back into the Material Plane (50% chance for either of the latter results if they are lost or abandoned by you). Creatures unwilling to accompany you into the Plane of Shadow receive a Will saving throw, negating the effect if successful.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (561,'Shambler','shambler','Conjuration','Creation',NULL,NULL,'Druid 9, Plant 9','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Three or more shambling mounds, no two of which can be more than 30 ft. apart; see text','Seven days or seven months (D); see text','None','No','Summons 1d4+2 shambling mounds to fight for you.',NULL,NULL,NULL,NULL,'\n      <p>The <i>shambler</i> spell creates 1d4+2 shambling mounds with 11 HD each. The creatures willingly aid you in combat or battle, perform a specific mission, or serve as bodyguards. The creatures remain with you for seven days unless you dismiss them. If the shamblers are created only for guard duty, however, the duration of the spell is seven months. In this case, the shamblers can only be ordered to guard a specific site or location. Shamblers summoned to guard duty cannot move outside the spell\'s range, which is measured from the point where each first appeared.</p>\n      <p>The shamblers have resistance to fire as normal shambling mounds do only if the terrain is rainy, marshy, or damp.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shambler\" level=\"5\"><p><h5>Shambler</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 9, Plant 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Three or more shambling mounds, no two of which can be more than 30 ft. apart; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Seven days or seven months (D); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>The <i>shambler</i> spell creates 1d4+2 shambling mounds with 11 HD each. The creatures willingly aid you in combat or battle, perform a specific mission, or serve as bodyguards. The creatures remain with you for seven days unless you dismiss them. If the shamblers are created only for guard duty, however, the duration of the spell is seven months. In this case, the shamblers can only be ordered to guard a specific site or location. Shamblers summoned to guard duty cannot move outside the spell\'s range, which is measured from the point where each first appeared.</p><p>The shamblers have resistance to fire as normal shambling mounds do only if the terrain is rainy, marshy, or damp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (562,'Shapechange','shapechange','Transmutation',NULL,NULL,NULL,'Animal 9, Druid 9, Sorcerer/Wizard 9','V, S, F','1 standard action','Personal','You',NULL,NULL,'10 min./level (D)','None','No','Transforms you into any creature, and change forms once per round.',NULL,'An empty cocoon.',NULL,'A jade circlet worth no less than 1,500 gp, which you must place on your head when casting the spell. (The focus melds into your new form when you change shape.)','\n      <p>This spell functions like <i>polymorph</i>,  except that it enables you to assume the form of any single nonunique creature (of any type) from Fine to Colossal size. The assumed form cannot have more than your caster level in Hit Dice (to a maximum of 25 HD). Unlike <i>polymorph</i>,  this spell allows incorporeal or gaseous forms to be assumed.</p>\n      <p>You gain all extraordinary and supernatural abilities (both attacks and qualities) of the assumed form, but you lose your own supernatural abilities. You also gain the type of the new form in place of your own. The new form does not disorient you. Parts of your body or pieces of equipment that are separated from you do not revert to their original forms.</p>\n      <p>You can become just about anything you are familiar with. You can change form once each round as a free action. The change takes place either immediately before your regular action or immediately after it, but not during the action. If you use this spell to create a disguise, you get a +10 bonus on your Disguise check.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shapechange\" level=\"5\"><p><h5>Shapechange</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Animal 9, Druid 9, Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr></table><p>This spell functions like <i>polymorph</i>,  except that it enables you to assume the form of any single nonunique creature (of any type) from Fine to Colossal size. The assumed form cannot have more than your caster level in Hit Dice (to a maximum of 25 HD). Unlike <i>polymorph</i>,  this spell allows incorporeal or gaseous forms to be assumed.</p><p>You gain all extraordinary and supernatural abilities (both attacks and qualities) of the assumed form, but you lose your own supernatural abilities. You also gain the type of the new form in place of your own. The new form does not disorient you. Parts of your body or pieces of equipment that are separated from you do not revert to their original forms.</p><p>You can become just about anything you are familiar with. You can change form once each round as a free action. The change takes place either immediately before your regular action or immediately after it, but not during the action. If you use this spell to create a disguise, you get a +10 bonus on your Disguise check.</p><p><i>Focus:</i> A jade circlet worth no less than 1,500 gp, which you must place on your head when casting the spell. (The focus melds into your new form when you change shape.)</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (563,'Shatter','shatter','Evocation',NULL,'Sonic',NULL,'Bard 2, Chaos 2, Cleric 2, Destruction 2, Sorcerer/Wizard 2','V, S, M/DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','5-ft. -radius spread; or one solid object or one crystalline creature','5-ft. -radius spread; or one solid object or one crystalline creature',NULL,'Instantaneous','Will negates (object); Will negates (object) or Fortitude half; see text','Yes (object)','Sonic vibration damages objects or crystalline creatures.',NULL,NULL,'A chip of mica.',NULL,'\n      <p><i>shatter</i> creates a loud, ringing noise that breaks brittle, nonmagical objects; sunders a single solid, nonmagical object; or damages a crystalline creature.</p>\n      <p>Used as an area attack, <i>shatter</i> destroys nonmagical objects of crystal, glass, ceramic, or porcelain. All such objects within a 5-foot radius of the point of origin are smashed into dozens of pieces by the spell. Objects weighing more than 1 pound per your level are not affected, but all other objects of the appropriate composition are shattered.</p>\n      <p>Alternatively, you can target <i>shatter</i> against a single solid object, regardless of composition, weighing up to 10 pounds per caster level. Targeted against a crystalline creature (of any weight), <i>shatter</i> deals 1d6 points of sonic damage per caster level (maximum 10d6), with a Fortitude save for half damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shatter\" level=\"5\"><p><h5>Shatter</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Chaos 2, Cleric 2, Destruction 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area or Target:</b><br/></td><td>5-ft. -radius spread; or one solid object or one crystalline creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object); Will negates (object) or Fortitude half; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p><i>shatter</i> creates a loud, ringing noise that breaks brittle, nonmagical objects; sunders a single solid, nonmagical object; or damages a crystalline creature.</p><p>Used as an area attack, <i>shatter</i> destroys nonmagical objects of crystal, glass, ceramic, or porcelain. All such objects within a 5-foot radius of the point of origin are smashed into dozens of pieces by the spell. Objects weighing more than 1 pound per your level are not affected, but all other objects of the appropriate composition are shattered.</p><p>Alternatively, you can target <i>shatter</i> against a single solid object, regardless of composition, weighing up to 10 pounds per caster level. Targeted against a crystalline creature (of any weight), <i>shatter</i> deals 1d6 points of sonic damage per caster level (maximum 10d6), with a Fortitude save for half damage.</p><p><i>Arcane Material Component:</i> A chip of mica.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (564,'Shield','shield','Abjuration',NULL,'Force',NULL,'Sorcerer/Wizard 1','V, S','1 standard action','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'Invisible disc gives +4 to AC, blocks magic missiles.',NULL,NULL,NULL,NULL,'\n      <p><i>Shield</i> creates an invisible, tower shield-sized mobile disk of force that hovers in front of you. It negates <i>magic missile</i> attacks directed at you. The disk also provides a +4 shield bonus to AC. This bonus applies against incorporeal touch attacks, since it is a force effect. The <i>Shield</i> has no armor check penalty or arcane spell failure chance. Unlike with a normal tower shield, you can\'t use the <i>Shield</i> spell for cover.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shield\" level=\"5\"><p><h5>Shield</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr></table><p><i>Shield</i> creates an invisible, tower shield-sized mobile disk of force that hovers in front of you. It negates <i>magic missile</i> attacks directed at you. The disk also provides a +4 shield bonus to AC. This bonus applies against incorporeal touch attacks, since it is a force effect. The <i>Shield</i> has no armor check penalty or arcane spell failure chance. Unlike with a normal tower shield, you can\'t use the <i>Shield</i> spell for cover.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (565,'Shield of Faith','shield of faith','Abjuration',NULL,NULL,NULL,'Cleric 1','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes (harmless)','Aura grants +2 or higher deflection bonus.',NULL,'A small parchment with a bit of holy text written upon it.',NULL,NULL,'\n      <p>This spell creates a shimmering, magical field around the touched creature that averts attacks. The spell grants the subject a +2 deflection bonus to AC, with an additional +1 to the bonus for every six levels you have (maximum +5 deflection bonus at 18th level).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shield of Faith\" level=\"5\"><p><h5>Shield of Faith</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>This spell creates a shimmering, magical field around the touched creature that averts attacks. The spell grants the subject a +2 deflection bonus to AC, with an additional +1 to the bonus for every six levels you have (maximum +5 deflection bonus at 18th level).</p><p><i>Material Component:</i> A small parchment with a bit of holy text written upon it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (566,'Shield of Law','shield of law','Abjuration',NULL,'Lawful',NULL,'Cleric 8, Law 8','V, S, F','1 standard action','20 ft.','One creature/level in a 20-ft. -radius burst centered on you',NULL,NULL,'1 round/level (D)','See text','Yes (harmless)','+4 to AC, +4 resistance, and spell resistance 25 against chaotic spells.',NULL,NULL,NULL,'A tiny reliquary containing some sacred relic, such as a scrap of parchment from a lawful text. The reliquary costs at least 500 gp.','\n      <p>A dim, blue glow surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by chaotic creatures, and <i>slowing</i> chaotic creatures when they strike the subjects. This abjuration has four effects.</p>\n      <p>First, each warded creature gains a +4 deflection bonus to AC and a +4 resistance bonus on saves. Unlike <i>protection from chaos</i>, this benefit applies against all attacks, not just against attacks by chaotic creatures.</p>\n      <p>Second, a warded creature gains spell resistance 25 against chaotic spells and spells cast by chaotic creatures.</p>\n      <p>Third, the abjuration blocks possession and mental influence, just as <i>protection from chaos</i> does.</p>\n      <p>Finally, if a chaotic creature succeeds on a melee attack against a warded creature, the attacker is <i>slowed</i> (Will save negates, as the <i>Slow</i> spell, but against <i>shield of law</i>\'s save DC).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shield of Law\" level=\"5\"><p><h5>Shield of Law</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Lawful]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Law 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>20 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level in a 20-ft. -radius burst centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>A dim, blue glow surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by chaotic creatures, and <i>slowing</i> chaotic creatures when they strike the subjects. This abjuration has four effects.</p><p>First, each warded creature gains a +4 deflection bonus to AC and a +4 resistance bonus on saves. Unlike <i>protection from chaos</i>, this benefit applies against all attacks, not just against attacks by chaotic creatures.</p><p>Second, a warded creature gains spell resistance 25 against chaotic spells and spells cast by chaotic creatures.</p><p>Third, the abjuration blocks possession and mental influence, just as <i>protection from chaos</i> does.</p><p>Finally, if a chaotic creature succeeds on a melee attack against a warded creature, the attacker is <i>slowed</i> (Will save negates, as the <i>Slow</i> spell, but against <i>shield of law</i>\'s save DC).</p><p><i>Focus:</i> A tiny reliquary containing some sacred relic, such as a scrap of parchment from a lawful text. The reliquary costs at least 500 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (567,'Shield Other','shield other','Abjuration',NULL,NULL,NULL,'Cleric 2, Paladin 2, Protection 2','V, S, F','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 hour/level (D)','Will negates (harmless)','Yes (harmless)','You take half of subject\'s damage.',NULL,NULL,NULL,'A pair of platinum rings (worth at least 50 gp each) worn by both you and the warded creature.','\n      <p>This spell wards the subject and creates a mystic connection between you and the subject so that some of its wounds are transferred to you. The subject gains a +1 deflection bonus to AC and a +1 resistance bonus on saves. Additionally, the subject takes only half damage from all wounds and attacks (including that dealt by special abilities) that deal hit point damage. The amount of damage not taken by the warded creature is taken by you. Forms of harm that do not involve hit points, such as <i>charm</i> effects, temporary ability damage, level draining, and death effects, are not affected. If the subject suffers a reduction of hit points from a lowered Constitution score, the reduction is not split with you because it is not hit point damage. When the spell ends, subsequent damage is no longer divided between the subject and you, but damage already split is not reassigned to the subject.</p>\n      <p>If you and the subject of the spell move out of range of each other, the spell ends.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shield Other\" level=\"5\"><p><h5>Shield Other</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Paladin 2, Protection 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>This spell wards the subject and creates a mystic connection between you and the subject so that some of its wounds are transferred to you. The subject gains a +1 deflection bonus to AC and a +1 resistance bonus on saves. Additionally, the subject takes only half damage from all wounds and attacks (including that dealt by special abilities) that deal hit point damage. The amount of damage not taken by the warded creature is taken by you. Forms of harm that do not involve hit points, such as <i>charm</i> effects, temporary ability damage, level draining, and death effects, are not affected. If the subject suffers a reduction of hit points from a lowered Constitution score, the reduction is not split with you because it is not hit point damage. When the spell ends, subsequent damage is no longer divided between the subject and you, but damage already split is not reassigned to the subject.</p><p>If you and the subject of the spell move out of range of each other, the spell ends.</p><p><i>Focus:</i> A pair of platinum rings (worth at least 50 gp each) worn by both you and the warded creature.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (568,'Shillelagh','shillelagh','Transmutation',NULL,NULL,NULL,'Druid 1','V, S, DF','1 standard action','Touch','One touched nonmagical oak club or quarterstaff',NULL,NULL,'1 min./level','Will negates (object)','Yes (object)','Cudgel or quarterstaff becomes +1 weapon (1d10 damage) for 1 min./level.',NULL,NULL,NULL,NULL,'\n      <p>Your own nonmagical club or quarterstaff becomes a weapon with a +1 enhancement bonus on attack and damage rolls. (A quarterstaff gains this enhancement for both ends of the weapon.) It deals damage as if it were two size categories larger (a Small club or quarterstaff so transmuted deals 1d8 points of damage, a Medium 2d6, and a Large 3d6), +1 for its enhancement bonus. These effects only occur when the weapon is wielded by you. If you do not wield it, the weapon behaves as if unaffected by this spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shillelagh\" level=\"5\"><p><h5>Shillelagh</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One touched nonmagical oak club or quarterstaff<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>Your own nonmagical club or quarterstaff becomes a weapon with a +1 enhancement bonus on attack and damage rolls. (A quarterstaff gains this enhancement for both ends of the weapon.) It deals damage as if it were two size categories larger (a Small club or quarterstaff so transmuted deals 1d8 points of damage, a Medium 2d6, and a Large 3d6), +1 for its enhancement bonus. These effects only occur when the weapon is wielded by you. If you do not wield it, the weapon behaves as if unaffected by this spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (569,'Shocking Grasp','shocking grasp','Evocation',NULL,'Electricity',NULL,'Sorcerer/Wizard 1','V, S','1 standard action','Touch','Creature or object touched',NULL,NULL,'Instantaneous','None','Yes','Touch delivers 1d6/level electricity damage (max 5d6).',NULL,NULL,NULL,NULL,'\n      <p>Your successful melee touch attack deals 1d6 points of electricity damage per caster level (maximum 5d6). When delivering the jolt, you gain a +3 bonus on attack rolls if the opponent is wearing metal armor (or made out of metal, carrying a lot of metal, or the like).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shocking Grasp\" level=\"5\"><p><h5>Shocking Grasp</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Electricity]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature or object touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Your successful melee touch attack deals 1d6 points of electricity damage per caster level (maximum 5d6). When delivering the jolt, you gain a +3 bonus on attack rolls if the opponent is wearing metal armor (or made out of metal, carrying a lot of metal, or the like).</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (570,'Shout','shout','Evocation',NULL,'Sonic',NULL,'Bard 4, Sorcerer/Wizard 4','V','1 standard action','30 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','Fortitude partial or Reflex negates (object); see text','Yes (object)','Deafens all within cone and deals 5d6 sonic damage.',NULL,NULL,NULL,NULL,'\n      <p>You emit an ear-splitting yell that deafens and damages creatures in its path. Any creature within the area is deafened for 2d6 rounds and takes 5d6 points of sonic damage. A successful save negates the deafness and reduces the damage by half. Any exposed brittle or crystalline object or crystalline creature takes 1d6 points of sonic damage per caster level (maximum 15d6). An affected creature is allowed a Fortitude save to reduce the damage by half, and a creature holding fragile objects can negate damage to them with a successful Reflex save.</p>\n      <p>A <i>shout</i> spell cannot penetrate a <i>silence</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shout\" level=\"5\"><p><h5>Shout</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>30 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial or Reflex negates (object); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>You emit an ear-splitting yell that deafens and damages creatures in its path. Any creature within the area is deafened for 2d6 rounds and takes 5d6 points of sonic damage. A successful save negates the deafness and reduces the damage by half. Any exposed brittle or crystalline object or crystalline creature takes 1d6 points of sonic damage per caster level (maximum 15d6). An affected creature is allowed a Fortitude save to reduce the damage by half, and a creature holding fragile objects can negate damage to them with a successful Reflex save.</p><p>A <i>shout</i> spell cannot penetrate a <i>silence</i> spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (571,'Shout, Greater','greater shout','Evocation',NULL,'Sonic',NULL,'Bard 6, Sorcerer/Wizard 8','V, S, F','1 standard action','60 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','Fortitude partial or Reflex negates (object); see text','Yes (object)','Devastating yell deals 10d6 sonic damage; stuns creatures, damages objects.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>shout</i>,  except that the cone deals 10d6 points of sonic damage (or 1d6 points of sonic damage per caster level, maximum 20d6, against exposed brittle or crystalline objects or crystalline creatures). It also causes creatures to be stunned for 1 round and deafened for 4d6 rounds. A creature in the area of the cone can negate the stunning and halve both the damage and the duration of the deafness with a successful Fortitude save. A creature holding vulnerable objects can attempt a Reflex save to negate the damage to those objects.</p>\n      <p/>\n    ',NULL,'A small metal or ivory horn.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shout, Greater\" level=\"5\"><p><h5>Shout, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial or Reflex negates (object); see text<br/></td></tr></table><p>This spell functions like <i>shout</i>,  except that the cone deals 10d6 points of sonic damage (or 1d6 points of sonic damage per caster level, maximum 20d6, against exposed brittle or crystalline objects or crystalline creatures). It also causes creatures to be stunned for 1 round and deafened for 4d6 rounds. A creature in the area of the cone can negate the stunning and halve both the damage and the duration of the deafness with a successful Fortitude save. A creature holding vulnerable objects can attempt a Reflex save to negate the damage to those objects.</p><p><i>Arcane Focus:</i> A small metal or ivory horn.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (572,'Shrink Item','shrink item','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 3','V, S','1 standard action','Touch','One touched object of up to 2 cu. ft./level',NULL,NULL,'One day/level; see text','Will negates (object)','Yes (object)','Object shrinks to one-sixteenth size.',NULL,NULL,NULL,NULL,'\n      <p>You are able to shrink one nonmagical item (if it is within the size limit) to 1/16 of its normal size in each dimension (to about 1/4,000 the original volume and mass). This change effectively reduces the object\'s size by four categories. Optionally, you can also change its now shrunken composition to a clothlike one. Objects changed by a <i>shrink item</i> spell can be returned to normal composition and size merely by tossing them onto any solid surface or by a word of command from the original caster. Even a burning fire and its fuel can be shrunk by this spell. Restoring the shrunken object to its normal size and composition ends the spell.</p>\n      <p><i>shrink item</i> can be made permanent with a <i>permanency</i> spell, in which case the affected object can be shrunk and expanded an indefinite number of times, but only by the original caster.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Shrink Item\" level=\"5\"><p><h5>Shrink Item</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One touched object of up to 2 cu. ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>You are able to shrink one nonmagical item (if it is within the size limit) to 1/16 of its normal size in each dimension (to about 1/4,000 the original volume and mass). This change effectively reduces the object\'s size by four categories. Optionally, you can also change its now shrunken composition to a clothlike one. Objects changed by a <i>shrink item</i> spell can be returned to normal composition and size merely by tossing them onto any solid surface or by a word of command from the original caster. Even a burning fire and its fuel can be shrunk by this spell. Restoring the shrunken object to its normal size and composition ends the spell.</p><p><i>shrink item</i> can be made permanent with a <i>permanency</i> spell, in which case the affected object can be shrunk and expanded an indefinite number of times, but only by the original caster.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (573,'Silence','silence','Illusion','Glamer',NULL,NULL,'Bard 2, Cleric 2','V, S','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'20-ft. -radius emanation centered on a creature, object, or point in space',NULL,'1 min./level (D)','Will negates; see text or none (object)','Yes; see text or no (object)','Negates sound in 20-ft. radius.',NULL,NULL,NULL,NULL,'\n      <p>Upon the casting of this spell, complete silence prevails in the affected area. All sound is stopped: Conversation is impossible, spells with verbal components cannot be cast, and no noise whatsoever issues from, enters, or passes through the area. The spell can be cast on a point in space, but the effect is stationary unless cast on a mobile object. The spell can be centered on a creature, and the effect then radiates from the creature and moves as it moves. An unwilling creature can attempt a Will save to negate the spell and can use spell resistance, if any. Items in a creature\'s possession or magic items that emit sound receive the benefits of saves and spell resistance, but unattended objects and points in space do not. This spell provides a defense against sonic or language-based attacks.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Silence\" level=\"5\"><p><h5>Silence</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius emanation centered on a creature, object, or point in space<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text or none (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes; see text or no (object)<br/></td></tr></table><p>Upon the casting of this spell, complete silence prevails in the affected area. All sound is stopped: Conversation is impossible, spells with verbal components cannot be cast, and no noise whatsoever issues from, enters, or passes through the area. The spell can be cast on a point in space, but the effect is stationary unless cast on a mobile object. The spell can be centered on a creature, and the effect then radiates from the creature and moves as it moves. An unwilling creature can attempt a Will save to negate the spell and can use spell resistance, if any. Items in a creature\'s possession or magic items that emit sound receive the benefits of saves and spell resistance, but unattended objects and points in space do not. This spell provides a defense against sonic or language-based attacks.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (574,'Silent Image','silent image','Illusion','Figment',NULL,NULL,'Bard 1, Sorcerer/Wizard 1','V, S, F','1 standard action','Long (400 ft. + 40 ft./level)',NULL,NULL,'Visual figment that cannot extend beyond four 10-ft. cubes + one 10-ft. cube/level (S)','Concentration','Will disbelief (if interacted with)','No','Creates minor illusion of your design.',NULL,NULL,NULL,'A bit of fleece.','\n      <p>This spell creates the visual illusion of an object, creature, or force, as visualized by you. The illusion does not create sound, smell, texture, or temperature. You can move the image within the limits of the size of the effect.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Silent Image\" level=\"5\"><p><h5>Silent Image</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Figment)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Visual figment that cannot extend beyond four 10-ft. cubes + one 10-ft. cube/level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will disbelief (if interacted with)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell creates the visual illusion of an object, creature, or force, as visualized by you. The illusion does not create sound, smell, texture, or temperature. You can move the image within the limits of the size of the effect.</p><p><i>Focus:</i> A bit of fleece.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (575,'Simulacrum','simulacrum','Illusion','Shadow',NULL,NULL,'Sorcerer/Wizard 7','V, S, M, XP','12 hours','0 ft.',NULL,NULL,'One duplicate creature','Instantaneous','None','No','Creates partially real double of a creature.',NULL,'The spell is cast over the rough snow or ice form, and some piece of the creature to be duplicated (hair, nail, or the like) must be placed inside the snow or ice. Additionally, the spell requires powdered ruby worth 100 gp per HD of the simulacrum to be created.',NULL,NULL,'\n      <p><i>Simulacrum</i> creates an illusory duplicate of any creature. The duplicate creature is partially real and formed from ice or snow. It appears to be the same as the original, but it has only one-half of the real creature\'s levels or Hit Dice (and the appropriate hit points, feats, skill ranks, and special abilities for a creature of that level or HD). You can\'t create a simulacrum of a creature whose Hit Dice or levels exceed twice your caster level. You must make a Disguise check when you cast the spell to determine how good the likeness is. A creature familiar with the original might detect the ruse with a successful Spot check (opposed by the caster\'s Disguise check) or a DC 20 Sense Motive check.</p>\n      <p>At all times the simulacrum remains under your absolute command. No special telepathic link exists, so command must be exercised in some other manner. A simulacrum has no ability to become more powerful. It cannot increase its level or abilities. If reduced to 0 hit points or otherwise destroyed, it reverts to snow and melts instantly into nothingness. A complex process requiring at least 24 hours, 100 gp per hit point, and a fully equipped magical laboratory can repair damage to a simulacrum.</p>\n      <p/>\n    ','100 XP per HD of the simulacrum to be created (minimum 1,000 XP).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Simulacrum\" level=\"5\"><p><h5>Simulacrum</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Shadow)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>12 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One duplicate creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p><i>Simulacrum</i> creates an illusory duplicate of any creature. The duplicate creature is partially real and formed from ice or snow. It appears to be the same as the original, but it has only one-half of the real creature\'s levels or Hit Dice (and the appropriate hit points, feats, skill ranks, and special abilities for a creature of that level or HD). You can\'t create a simulacrum of a creature whose Hit Dice or levels exceed twice your caster level. You must make a Disguise check when you cast the spell to determine how good the likeness is. A creature familiar with the original might detect the ruse with a successful Spot check (opposed by the caster\'s Disguise check) or a DC 20 Sense Motive check.</p><p>At all times the simulacrum remains under your absolute command. No special telepathic link exists, so command must be exercised in some other manner. A simulacrum has no ability to become more powerful. It cannot increase its level or abilities. If reduced to 0 hit points or otherwise destroyed, it reverts to snow and melts instantly into nothingness. A complex process requiring at least 24 hours, 100 gp per hit point, and a fully equipped magical laboratory can repair damage to a simulacrum.</p><p><i>Material Component:</i> The spell is cast over the rough snow or ice form, and some piece of the creature to be duplicated (hair, nail, or the like) must be placed inside the snow or ice. Additionally, the spell requires powdered ruby worth 100 gp per HD of the simulacrum to be created.</p><p><i>XP Cost:</i> 100 XP per HD of the simulacrum to be created (minimum 1,000 XP).</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (576,'Slay Living','slay living','Necromancy',NULL,'Death',NULL,'Cleric 5, Death 5','V, S','1 standard action','Touch','Living creature touched',NULL,NULL,'Instantaneous','Fortitude partial','Yes','Touch attack kills subject.',NULL,NULL,NULL,NULL,'\n      <p>You can slay any one living creature. You must succeed on a melee touch attack to touch the subject, and it can avoid death with a successful Fortitude save. If it succeeds, it instead takes 3d6 points of damage +1 point per caster level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Slay Living\" level=\"5\"><p><h5>Slay Living</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Death 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You can slay any one living creature. You must succeed on a melee touch attack to touch the subject, and it can avoid death with a successful Fortitude save. If it succeeds, it instead takes 3d6 points of damage +1 point per caster level.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (577,'Sleep','sleep','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 1, Sorcerer/Wizard 1','V, S, M','1 round','Medium (100 ft. + 10 ft./level)',NULL,'One or more living creatures within a 10-ft. -radius burst',NULL,'1 min./level','Will negates','Yes','Puts 4 HD of creatures into magical slumber.',NULL,'A pinch of fine sand, rose petals, or a live cricket.',NULL,NULL,'\n      <p>A <i>sleep</i> spell causes a magical slumber to come upon 4 Hit Dice of creatures. Creatures with the fewest HD are affected first.</p>\n      <p>Among creatures with equal HD, those who are closest to the spell\'s point of origin are affected first. Hit Dice that are not sufficient to affect a creature are wasted.</p>\n      <p>Sleeping creatures are helpless. Slapping or wounding awakens an affected creature, but normal noise does not. Awakening a creature is a standard action (an application of the aid another action).</p>\n      <p><i>sleep</i> does not target unconscious creatures, constructs, or undead creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sleep\" level=\"5\"><p><h5>Sleep</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>One or more living creatures within a 10-ft. -radius burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A <i>sleep</i> spell causes a magical slumber to come upon 4 Hit Dice of creatures. Creatures with the fewest HD are affected first.</p><p>Among creatures with equal HD, those who are closest to the spell\'s point of origin are affected first. Hit Dice that are not sufficient to affect a creature are wasted.</p><p>Sleeping creatures are helpless. Slapping or wounding awakens an affected creature, but normal noise does not. Awakening a creature is a standard action (an application of the aid another action).</p><p><i>sleep</i> does not target unconscious creatures, constructs, or undead creatures.</p><p><i>Material Component:</i> A pinch of fine sand, rose petals, or a live cricket.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (578,'Sleet Storm','sleet storm','Conjuration','Creation','Cold',NULL,'Druid 3, Sorcerer/Wizard 3','V, S, M/DF','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'Cylinder (40-ft. radius, 20 ft. high)',NULL,'1 round/level','None','No','Hampers vision and movement.',NULL,NULL,'A pinch of dust and a few drops of water.',NULL,'\n      <p>Driving sleet blocks all sight (even darkvision) within it and causes the ground in the area to be icy. A creature can walk within or through the area of sleet at half normal speed with a DC 10 Balance check. Failure means it can\'t move in that round, while failure by 5 or more means it falls (see the Balance skill for details).</p>\n      <p>The sleet extinguishes torches and small fires.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sleet Storm\" level=\"5\"><p><h5>Sleet Storm</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Cold]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cylinder (40-ft. radius, 20 ft. high)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Driving sleet blocks all sight (even darkvision) within it and causes the ground in the area to be icy. A creature can walk within or through the area of sleet at half normal speed with a DC 10 Balance check. Failure means it can\'t move in that round, while failure by 5 or more means it falls (see the Balance skill for details).</p><p>The sleet extinguishes torches and small fires.</p><p><i>Arcane Material Component:</i> A pinch of dust and a few drops of water.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (579,'Slow','slow','Transmutation',NULL,NULL,NULL,'Bard 3, Sorcerer/Wizard 3','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 round/level','Will negates','Yes','One subject/level takes only one action/round, -1 to AC, reflex saves, and attack rolls.',NULL,'A drop of molasses.',NULL,NULL,'\n      <p>An affected creature moves and attacks at a drastically slowed rate. A <i>slowed</i> creature can take only a single move action or standard action each turn, but not both (nor may it take full-round actions). Additionally, it takes a -1 penalty on attack rolls, AC, and Reflex saves. A <i>slowed</i> creature moves at half its normal speed (round down to the next 5-foot increment), which affects the creature\'s jumping distance as normal for decreased speed.</p>\n      <p>Multiple <i>Slow</i> effects don\'t stack. <i>Slow</i> counters and dispels <i>haste</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Slow\" level=\"5\"><p><h5>Slow</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>An affected creature moves and attacks at a drastically slowed rate. A <i>slowed</i> creature can take only a single move action or standard action each turn, but not both (nor may it take full-round actions). Additionally, it takes a -1 penalty on attack rolls, AC, and Reflex saves. A <i>slowed</i> creature moves at half its normal speed (round down to the next 5-foot increment), which affects the creature\'s jumping distance as normal for decreased speed.</p><p>Multiple <i>Slow</i> effects don\'t stack. <i>Slow</i> counters and dispels <i>haste</i>.</p><p><i>Material Component:</i> A drop of molasses.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (580,'Snare','snare','Transmutation',NULL,NULL,NULL,'Ranger 2, Druid 3','V, S, DF','3 rounds','Touch','Touched nonmagical circle of vine, rope, or thong with a 2 ft. diameter + 2 ft./level',NULL,NULL,'Until triggered or broken','None','No','Creates a magic booby trap.',NULL,NULL,NULL,NULL,'\n      <p>This spell enables you to make a snare that functions as a magic trap. The snare can be made from any supple vine, a thong, or a rope. When you cast <i>snare</i> upon it, the cordlike object blends with its surroundings (Search DC 23 for a character with the trapfinding ability to locate). One end of the snare is tied in a loop that contracts around one or more of the limbs of any creature stepping inside the circle.</p>\n      <p>If a strong and supple tree is nearby, the snare can be fastened to it. The spell causes the tree to bend and then straighten when the loop is triggered, dealing 1d6 points of damage to the creature trapped and lifting it off the ground by the trapped limb or limbs. If no such tree is available, the cordlike object tightens around the creature, dealing no damage but causing it to be entangled.</p>\n      <p>The snare is magical. To escape, a trapped creature must make a DC 23 Escape Artist check or a DC 23 Strength check that is a full-round action. The snare has AC 7 and 5 hit points. A successful escape from the snare breaks the loop and ends the spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Snare\" level=\"5\"><p><h5>Snare</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Ranger 2, Druid 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>3 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Touched nonmagical circle of vine, rope, or thong with a 2 ft. diameter + 2 ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Until triggered or broken<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell enables you to make a snare that functions as a magic trap. The snare can be made from any supple vine, a thong, or a rope. When you cast <i>snare</i> upon it, the cordlike object blends with its surroundings (Search DC 23 for a character with the trapfinding ability to locate). One end of the snare is tied in a loop that contracts around one or more of the limbs of any creature stepping inside the circle.</p><p>If a strong and supple tree is nearby, the snare can be fastened to it. The spell causes the tree to bend and then straighten when the loop is triggered, dealing 1d6 points of damage to the creature trapped and lifting it off the ground by the trapped limb or limbs. If no such tree is available, the cordlike object tightens around the creature, dealing no damage but causing it to be entangled.</p><p>The snare is magical. To escape, a trapped creature must make a DC 23 Escape Artist check or a DC 23 Strength check that is a full-round action. The snare has AC 7 and 5 hit points. A successful escape from the snare breaks the loop and ends the spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (581,'Soften Earth and Stone','soften earth and stone','Transmutation',NULL,'Earth',NULL,'Druid 2, Earth 2','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'10-ft. square/level; see text',NULL,'Instantaneous','None','No','Turns stone to clay or dirt to sand or mud.',NULL,NULL,NULL,NULL,'\n      <p>When this spell is cast, all natural, undressed earth or stone in the spell\'s area is softened. Wet earth becomes thick mud, dry earth becomes loose sand or dirt, and stone becomes soft clay that is easily molded or chopped. You affect a 10-footsquare area to a depth of 1 to 4 feet, depending on the toughness or resilience of the ground at that spot. Magical, enchanted, dressed, or worked stone cannot be affected. Earth or stone creatures are not affected.</p>\n      <p>A creature in mud must succeed on a Reflex save or be caught for 1d2 rounds and unable to move, attack, or cast spells. A creature that succeeds on its save can move through the mud at half speed, and it can\'t run or charge.</p>\n      <p>Loose dirt is not as troublesome as mud, but all creatures in the area can move at only half their normal speed and can\'t run or charge over the surface.</p>\n      <p>Stone softened into clay does not hinder movement, but it does allow characters to cut, shape, or excavate areas they may not have been able to affect before.</p>\n      <p>While <i>soften earth and stone</i> does not affect dressed or worked stone, cavern ceilings or vertical surfaces such as cliff faces can be affected. Usually, this causes a moderate collapse or landslide as the loosened material peels away from the face of the wall or roof and falls.</p>\n      <p>A moderate amount of structural damage can be dealt to a manufactured structure by softening the ground beneath it, causing it to settle. However, most well-built structures will only be damaged by this spell, not destroyed.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Soften Earth and Stone\" level=\"5\"><p><h5>Soften Earth and Stone</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 2, Earth 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. square/level; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>When this spell is cast, all natural, undressed earth or stone in the spell\'s area is softened. Wet earth becomes thick mud, dry earth becomes loose sand or dirt, and stone becomes soft clay that is easily molded or chopped. You affect a 10-footsquare area to a depth of 1 to 4 feet, depending on the toughness or resilience of the ground at that spot. Magical, enchanted, dressed, or worked stone cannot be affected. Earth or stone creatures are not affected.</p><p>A creature in mud must succeed on a Reflex save or be caught for 1d2 rounds and unable to move, attack, or cast spells. A creature that succeeds on its save can move through the mud at half speed, and it can\'t run or charge.</p><p>Loose dirt is not as troublesome as mud, but all creatures in the area can move at only half their normal speed and can\'t run or charge over the surface.</p><p>Stone softened into clay does not hinder movement, but it does allow characters to cut, shape, or excavate areas they may not have been able to affect before.</p><p>While <i>soften earth and stone</i> does not affect dressed or worked stone, cavern ceilings or vertical surfaces such as cliff faces can be affected. Usually, this causes a moderate collapse or landslide as the loosened material peels away from the face of the wall or roof and falls.</p><p>A moderate amount of structural damage can be dealt to a manufactured structure by softening the ground beneath it, causing it to settle. However, most well-built structures will only be damaged by this spell, not destroyed.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (582,'Solid Fog','solid fog','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 4','V, S, M','1 standard action','Medium (100 ft. + 10 ft. level)',NULL,NULL,'Fog spreads in 20-ft. radius, 20 ft. high','1 min./level','None','No','Blocks vision and slows movement.',NULL,'A pinch of dried, powdered peas combined with powdered animal hoof.',NULL,NULL,'\n      <p>This spell functions like <i>fog cloud</i>, but in addition to obscuring sight, the <i>Solid fog</i> is so thick that any creature attempting to move through it progresses at a speed of 5 feet, regardless of its normal speed, and it takes a -2 penalty on all melee attack and melee damage rolls. The vapors prevent effective ranged weapon attacks (except for magic rays and the like). A creature or object that falls into <i>Solid fog</i> is slowed, so that each 10 feet of vapor that it passes through reduces falling damage by 1d6. A creature can\'t take a 5-foot step while in <i>solid fog</i>.</p>\n      <p>However, unlike normal fog, only a severe wind (31+ mph) disperses these vapors, and it does so in 1 round.</p>\n      <p><i>Solid fog</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>Solid fog</i> dispersed by wind reforms in 10 minutes.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Solid Fog\" level=\"5\"><p><h5>Solid Fog</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell functions like <i>fog cloud</i>, but in addition to obscuring sight, the <i>Solid fog</i> is so thick that any creature attempting to move through it progresses at a speed of 5 feet, regardless of its normal speed, and it takes a -2 penalty on all melee attack and melee damage rolls. The vapors prevent effective ranged weapon attacks (except for magic rays and the like). A creature or object that falls into <i>Solid fog</i> is slowed, so that each 10 feet of vapor that it passes through reduces falling damage by 1d6. A creature can\'t take a 5-foot step while in <i>solid fog</i>.</p><p>However, unlike normal fog, only a severe wind (31+ mph) disperses these vapors, and it does so in 1 round.</p><p><i>Solid fog</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>Solid fog</i> dispersed by wind reforms in 10 minutes.</p><p><i>Material Component:</i> A pinch of dried, powdered peas combined with powdered animal hoof.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (583,'Song of Discord','song of discord','Enchantment','Compulsion','Mind-Affecting, Sonic',NULL,'Bard 5','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Creatures within a 20-ft. -radius spread',NULL,'1 round/level','Will negates','Yes','Forces targets to attack each other.',NULL,NULL,NULL,NULL,'\n      <p>This spell causes those within the area to turn on each other rather than attack their foes. Each affected creature has a 50% chance to attack the nearest target each round. (Roll to determine each creature\'s behavior every round at the beginning of its turn.) A creature that does not attack its nearest neighbor is free to act normally for that round.</p>\n      <p>Creatures forced by a <i>song of discord</i> to attack their fellows employ all methods at their disposal, choosing their deadliest spells and most advantageous combat tactics. They do not, however, harm targets that have fallen unconscious.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Song of Discord\" level=\"5\"><p><h5>Song of Discord</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting, Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Creatures within a 20-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell causes those within the area to turn on each other rather than attack their foes. Each affected creature has a 50% chance to attack the nearest target each round. (Roll to determine each creature\'s behavior every round at the beginning of its turn.) A creature that does not attack its nearest neighbor is free to act normally for that round.</p><p>Creatures forced by a <i>song of discord</i> to attack their fellows employ all methods at their disposal, choosing their deadliest spells and most advantageous combat tactics. They do not, however, harm targets that have fallen unconscious.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (584,'Soul Bind','soul bind','Necromancy',NULL,NULL,NULL,'Cleric 9, Sorcerer/Wizard 9','V, S, F','1 standard action','Close (25 ft. + 5 ft./2 levels)','Corpse',NULL,NULL,'Permanent','Will negates','No','Traps newly dead soul to prevent resurrection.',NULL,NULL,NULL,'A black sapphire of at least 1,000 gp value for every Hit Die possessed by the creature whose soul is to be bound. If the gem is not valuable enough, it shatters when the binding is attempted. (While creatures have no concept of level or Hit Dice as such, the value of the gem needed to trap an individual can be researched. Remember that this value can change over time as creatures gain more Hit Dice.)','\n      <p>You draw the soul from a newly dead body and imprison it in a black sapphire gem. The subject must have been dead no more than 1 round per caster level. The soul, once trapped in the gem, cannot be returned through <i>clone</i>,  <i>raise dead</i>,  <i>reincarnation</i>,  <i>resurrection</i>,  <i>true resurrection</i>,  or even a <i>miracle</i> or a <i>wish</i>. Only by destroying the gem or dispelling the spell on the gem can one free the soul (which is then still dead).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Soul Bind\" level=\"5\"><p><h5>Soul Bind</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 9, Sorcerer/Wizard 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Corpse<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You draw the soul from a newly dead body and imprison it in a black sapphire gem. The subject must have been dead no more than 1 round per caster level. The soul, once trapped in the gem, cannot be returned through <i>clone</i>,  <i>raise dead</i>,  <i>reincarnation</i>,  <i>resurrection</i>,  <i>true resurrection</i>,  or even a <i>miracle</i> or a <i>wish</i>. Only by destroying the gem or dispelling the spell on the gem can one free the soul (which is then still dead).</p><p><i>Focus:</i> A black sapphire of at least 1,000 gp value for every Hit Die possessed by the creature whose soul is to be bound. If the gem is not valuable enough, it shatters when the binding is attempted. (While creatures have no concept of level or Hit Dice as such, the value of the gem needed to trap an individual can be researched. Remember that this value can change over time as creatures gain more Hit Dice.)</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (585,'Sound Burst','sound burst','Evocation',NULL,'Sonic',NULL,'Bard 2, Cleric 2','V, S, F/DF','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'10-ft. -radius spread',NULL,'Instantaneous','Fortitude partial','Yes','Deals 1d8 sonic damage to subjects; may stun them.',NULL,NULL,NULL,NULL,'\n      <p>You blast an area with a tremendous cacophony. Every creature in the area takes 1d8 points of sonic damage and must succeed on a Fortitude save to avoid being stunned for 1 round.</p>\n      <p>Creatures that cannot hear are not stunned but are still damaged.</p>\n      <p/>\n    ',NULL,'A musical instrument.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Sound Burst\" level=\"5\"><p><h5>Sound Burst</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>10-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You blast an area with a tremendous cacophony. Every creature in the area takes 1d8 points of sonic damage and must succeed on a Fortitude save to avoid being stunned for 1 round.</p><p>Creatures that cannot hear are not stunned but are still damaged.</p><p><i>Arcane Focus:</i> A musical instrument.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (586,'Speak with Animals','speak with animals','Divination',NULL,NULL,NULL,'Bard 3, Druid 1, Ranger 1','V, S','1 standard action','Personal','You',NULL,NULL,'1 min./level',NULL,NULL,'You can communicate with animals.',NULL,NULL,NULL,NULL,'\n      <p>You can comprehend and communicate with animals. You are able to ask questions of and receive answers from animals, although the spell doesn\'t make them any more friendly or cooperative than normal. Furthermore, wary and cunning animals are likely to be terse and evasive, while the more stupid ones make inane comments. If an animal is friendly toward you, it may do some favor or service for you.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Speak with Animals\" level=\"5\"><p><h5>Speak with Animals</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Druid 1, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr></table><p>You can comprehend and communicate with animals. You are able to ask questions of and receive answers from animals, although the spell doesn\'t make them any more friendly or cooperative than normal. Furthermore, wary and cunning animals are likely to be terse and evasive, while the more stupid ones make inane comments. If an animal is friendly toward you, it may do some favor or service for you.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (587,'Speak with Dead','speak with dead','Necromancy',NULL,'Language-Dependent',NULL,'Cleric 3','V, S, DF','10 minutes','10 ft.','One dead creature',NULL,NULL,'1 min./level','Will negates; see text','No','Corpse answers one question/two levels.',NULL,NULL,NULL,NULL,'\n      <p>You grant the semblance of life and intellect to a corpse, allowing it to answer several questions that you put to it. You may ask one question per two caster levels. Unasked questions are wasted if the duration expires. The corpse\'s knowledge is limited to what the creature knew during life, including the languages it spoke (if any). Answers are usually brief, cryptic, or repetitive. If the creature\'s alignment was different from yours, the corpse gets a Will save to resist the spell as if it were alive.</p>\n      <p>If the corpse has been subject to <i>speak with dead</i> within the past week, the new spell fails. You can cast this spell on a corpse that has been deceased for any amount of time, but the body must be mostly intact to be able to respond. A damaged corpse may be able to give partial answers or partially correct answers, but it must at least have a mouth in order to speak at all.</p>\n      <p>This spell does not let you actually speak to the person (whose soul has departed). It instead draws on the imprinted knowledge stored in the corpse. The partially animated body retains the imprint of the soul that once inhabited it, and thus it can speak with all the knowledge that the creature had while alive. The corpse, however, cannot learn new information.</p>\n      <p>Indeed, it can\'t even remember being questioned.</p>\n      <p>This spell does not affect a corpse that has been turned into an undead creature.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Speak with Dead\" level=\"5\"><p><h5>Speak with Dead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Language-Dependent]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>10 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One dead creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You grant the semblance of life and intellect to a corpse, allowing it to answer several questions that you put to it. You may ask one question per two caster levels. Unasked questions are wasted if the duration expires. The corpse\'s knowledge is limited to what the creature knew during life, including the languages it spoke (if any). Answers are usually brief, cryptic, or repetitive. If the creature\'s alignment was different from yours, the corpse gets a Will save to resist the spell as if it were alive.</p><p>If the corpse has been subject to <i>speak with dead</i> within the past week, the new spell fails. You can cast this spell on a corpse that has been deceased for any amount of time, but the body must be mostly intact to be able to respond. A damaged corpse may be able to give partial answers or partially correct answers, but it must at least have a mouth in order to speak at all.</p><p>This spell does not let you actually speak to the person (whose soul has departed). It instead draws on the imprinted knowledge stored in the corpse. The partially animated body retains the imprint of the soul that once inhabited it, and thus it can speak with all the knowledge that the creature had while alive. The corpse, however, cannot learn new information.</p><p>Indeed, it can\'t even remember being questioned.</p><p>This spell does not affect a corpse that has been turned into an undead creature.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (588,'Speak with Plants','speak with plants','Divination',NULL,NULL,NULL,'Bard 4, Druid 3, Ranger 2','V, S','1 standard action','Personal','You',NULL,NULL,'1 min./level',NULL,NULL,'You can talk to normal plants and plant creatures.',NULL,NULL,NULL,NULL,'\n      <p>You can comprehend and communicate with plants, including both normal plants and plant creatures. You are able to ask questions of and receive answers from plants. A regular plant\'s sense of its surroundings is limited, so it won\'t be able to give (or recognize) detailed descriptions of creatures or answer questions about events outside its immediate vicinity.</p>\n      <p>The spell doesn\'t make plant creatures any more friendly or cooperative than normal. Furthermore, wary and cunning plant creatures are likely to be terse and evasive, while the more stupid ones may make inane comments. If a plant creature is friendly toward you, it may do some favor or service for you.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Speak with Plants\" level=\"5\"><p><h5>Speak with Plants</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Druid 3, Ranger 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr></table><p>You can comprehend and communicate with plants, including both normal plants and plant creatures. You are able to ask questions of and receive answers from plants. A regular plant\'s sense of its surroundings is limited, so it won\'t be able to give (or recognize) detailed descriptions of creatures or answer questions about events outside its immediate vicinity.</p><p>The spell doesn\'t make plant creatures any more friendly or cooperative than normal. Furthermore, wary and cunning plant creatures are likely to be terse and evasive, while the more stupid ones may make inane comments. If a plant creature is friendly toward you, it may do some favor or service for you.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (589,'Spectral Hand','spectral hand','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 2','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'One spectral hand','1 min./level (D)','None','No','Creates disembodied glowing hand to deliver touch attacks.',NULL,NULL,NULL,NULL,'\n      <p>A ghostly, glowing hand shaped from your life force materializes and moves as you desire, allowing you to deliver low-level, touch range spells at a distance. On casting the spell, you lose 1d4 hit points that return when the spell ends (even if it is dispelled), but not if the hand is destroyed. (The hit points can be healed as normal.) For as long as the spell lasts, any touch range spell of 4th level or lower that you cast can be delivered by the <i>spectral hand</i>. The spell gives you a +2 bonus on your melee touch attack roll, and attacking with the hand counts normally as an attack. The hand always strikes from your direction. The hand cannot flank targets like a creature can. After it delivers a spell, or if the hand goes beyond the spell range, goes out of your sight, the hand returns to you and hovers.</p>\n      <p>The hand is incorporeal and thus cannot be harmed by normal weapons. It has improved evasion (half damage on a failed Reflex save and no damage on a successful save), your save bonuses, and an AC of at least 22. Your Intelligence modifier applies to the hand\'s AC as if it were the hand\'s Dexterity modifier. The hand has 1 to 4 hit points, the same number that you lost in creating it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spectral Hand\" level=\"5\"><p><h5>Spectral Hand</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One spectral hand<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A ghostly, glowing hand shaped from your life force materializes and moves as you desire, allowing you to deliver low-level, touch range spells at a distance. On casting the spell, you lose 1d4 hit points that return when the spell ends (even if it is dispelled), but not if the hand is destroyed. (The hit points can be healed as normal.) For as long as the spell lasts, any touch range spell of 4th level or lower that you cast can be delivered by the <i>spectral hand</i>. The spell gives you a +2 bonus on your melee touch attack roll, and attacking with the hand counts normally as an attack. The hand always strikes from your direction. The hand cannot flank targets like a creature can. After it delivers a spell, or if the hand goes beyond the spell range, goes out of your sight, the hand returns to you and hovers.</p><p>The hand is incorporeal and thus cannot be harmed by normal weapons. It has improved evasion (half damage on a failed Reflex save and no damage on a successful save), your save bonuses, and an AC of at least 22. Your Intelligence modifier applies to the hand\'s AC as if it were the hand\'s Dexterity modifier. The hand has 1 to 4 hit points, the same number that you lost in creating it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (590,'Spell Immunity','spell immunity','Abjuration',NULL,NULL,NULL,'Cleric 4, Protection 4, Strength 4','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'10 min./level','Will negates (harmless)','Yes (harmless)','Subject is immune to one spell per four levels.',NULL,NULL,NULL,NULL,'\n      <p>The warded creature is immune to the effects of one specified spell for every four levels you have. The spells must be of 4th level or lower. The warded creature effectively has unbeatable spell resistance regarding the specified spell or spells. Naturally, that immunity doesn\'t protect a creature from spells for which spell resistance doesn\'t apply. <i>spell immunity</i> protects against spells, spell-like effects of magic items, and innate spell-like abilities of creatures. It does not protect against supernatural or extraordinary abilities, such as breath weapons or gaze attacks.</p>\n      <p>Only a particular spell can be protected against, not a certain domain or school of spells or a group of spells that are similar in effect.</p>\n      <p>A creature can have only one <i>spell immunity</i> or <i>greater spell immunity</i> spell in effect on it at a time.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spell Immunity\" level=\"5\"><p><h5>Spell Immunity</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 4, Protection 4, Strength 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The warded creature is immune to the effects of one specified spell for every four levels you have. The spells must be of 4th level or lower. The warded creature effectively has unbeatable spell resistance regarding the specified spell or spells. Naturally, that immunity doesn\'t protect a creature from spells for which spell resistance doesn\'t apply. <i>spell immunity</i> protects against spells, spell-like effects of magic items, and innate spell-like abilities of creatures. It does not protect against supernatural or extraordinary abilities, such as breath weapons or gaze attacks.</p><p>Only a particular spell can be protected against, not a certain domain or school of spells or a group of spells that are similar in effect.</p><p>A creature can have only one <i>spell immunity</i> or <i>greater spell immunity</i> spell in effect on it at a time.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (591,'Spell Immunity, Greater','greater spell immunity','Abjuration',NULL,NULL,NULL,'Cleric 8','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'10 min./level','Will negates (harmless)','Yes (harmless)','As spell immunity, but up to 8th-level spells.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>spell immunity</i>, except the immunity applies to spells of 8th level or lower.</p>\n      <p>A creature can have only one <i>spell immunity</i> or <i>greater spell immunity</i> spell in effect on it at a time.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spell Immunity, Greater\" level=\"5\"><p><h5>Spell Immunity, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8<br/></td></tr></table><p>This spell functions like <i>spell immunity</i>, except the immunity applies to spells of 8th level or lower.</p><p>A creature can have only one <i>spell immunity</i> or <i>greater spell immunity</i> spell in effect on it at a time.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (592,'Spell Resistance','spell resistance','Abjuration',NULL,NULL,NULL,'Cleric 5, Magic 5, Protection 5','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes (harmless)','Subject gains spell resistance 12 + level.',NULL,NULL,NULL,NULL,'\n      <p>The creature gains spell resistance equal to 12 + your caster level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spell Resistance\" level=\"5\"><p><h5>Spell Resistance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5, Magic 5, Protection 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The creature gains spell resistance equal to 12 + your caster level.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (593,'Spellstaff','spellstaff','Transmutation',NULL,NULL,NULL,'Druid 6','V, S, F','10 minutes','Touch','Wooden quarterstaff touched',NULL,NULL,'Permanent until discharged (D)','Will negates (object)','Yes (object)','Stores one spell in wooden quarterstaff.',NULL,NULL,NULL,'The staff that stores the spell.','\n      <p>You store one spell that you can normally cast in a wooden quarterstaff. Only one such spell can be stored in a staff at a given time, and you cannot have more than one <i>spellstaff</i> at any given time. You can cast a spell stored within a staff just as though it were among those you had prepared, but it does not count against your normal allotment for a given day. You use up any applicable material components required to cast the spell when you store it in the <i>spellstaff</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spellstaff\" level=\"5\"><p><h5>Spellstaff</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Wooden quarterstaff touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent until discharged (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>You store one spell that you can normally cast in a wooden quarterstaff. Only one such spell can be stored in a staff at a given time, and you cannot have more than one <i>spellstaff</i> at any given time. You can cast a spell stored within a staff just as though it were among those you had prepared, but it does not count against your normal allotment for a given day. You use up any applicable material components required to cast the spell when you store it in the <i>spellstaff</i>.</p><p><i>Focus:</i> The staff that stores the spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (594,'Spell Turning','spell turning','Abjuration',NULL,NULL,NULL,'Luck 7, Magic 7, Sorcerer/Wizard 7','V, S, M/DF','1 standard action','Personal','You',NULL,NULL,'Until expended or 10 min./level',NULL,NULL,'Reflect 1d4+6 spell levels back at caster.',NULL,NULL,'A small silver mirror.',NULL,'\n      <p>Spells and spell-like effects targeted on you are turned back upon the original caster. The abjuration turns only spells that have you as a target. Effect and area spells are not affected. <i>Spell turning</i> also fails to stop touch range spells.</p>\n      <p>From seven to ten (1d4+6) spell levels are affected by the turning. The exact number is rolled secretly.</p>\n      <p>When you are targeted by a spell of higher level than the amount of spell turning you have left, that spell is partially turned. The subtract the amount of spell turning left from the spell level of the incoming spell, then divide the result by the spell level of the incoming spell to see what fraction of the effect gets through. For damaging spells, you and the caster each take a fraction of the damage. For nondamaging spells, each of you has a proportional chance to be affected.</p>\n      <p>If you and a spellcasting attacker are both warded by <i>Spell turning</i> effects in operation, a resonating field is created.</p>\n      <p>Roll randomly to determine the result.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td>\n<td><b>Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-70<br/></td>\n<td>Spell drains away without effect.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>71-80<br/></td>\n<td>Spell affects both of you equally at full effect.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>81-97<br/></td>\n<td>Both turning effects are rendered nonfunctional for 1d4 minutes.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>98-100<br/></td>\n<td>Both of you go through a rift into another plane.<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spell Turning\" level=\"5\"><p><h5>Spell Turning</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Luck 7, Magic 7, Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Until expended or 10 min./level<br/></td></tr></table><p>Spells and spell-like effects targeted on you are turned back upon the original caster. The abjuration turns only spells that have you as a target. Effect and area spells are not affected. <i>Spell turning</i> also fails to stop touch range spells.</p><p>From seven to ten (1d4+6) spell levels are affected by the turning. The exact number is rolled secretly.</p><p>When you are targeted by a spell of higher level than the amount of spell turning you have left, that spell is partially turned. The subtract the amount of spell turning left from the spell level of the incoming spell, then divide the result by the spell level of the incoming spell to see what fraction of the effect gets through. For damaging spells, you and the caster each take a fraction of the damage. For nondamaging spells, each of you has a proportional chance to be affected.</p><p>If you and a spellcasting attacker are both warded by <i>Spell turning</i> effects in operation, a resonating field is created.</p><p>Roll randomly to determine the result.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td>\n<td><b>Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-70<br/></td>\n<td>Spell drains away without effect.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>71-80<br/></td>\n<td>Spell affects both of you equally at full effect.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>81-97<br/></td>\n<td>Both turning effects are rendered nonfunctional for 1d4 minutes.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>98-100<br/></td>\n<td>Both of you go through a rift into another plane.<br/></td>\n\n</tr>\n</table><p><i>Arcane Material Component:</i> A small silver mirror.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (595,'Spider Climb','spider climb','Transmutation',NULL,NULL,NULL,'Druid 2, Sorcerer/Wizard 2','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'10 min./level','Will negates (harmless)','Yes (harmless)','Grants ability to walk on walls and ceilings.',NULL,'A drop of bitumen and a live spider, both of which must be eaten by the subject.',NULL,NULL,'\n      <p>The subject can climb and travel on vertical surfaces or even traverse ceilings as well as a spider does. The affected creature must have its hands free to climb in this manner. The subject gains a climb speed of 20 feet; furthermore, it need not make Climb checks to traverse a vertical or horizontal surface (even upside down). A <i>spider climbing</i> creature retains its Dexterity bonus to Armor Class (if any) while climbing, and opponents get no special bonus to their attacks against it. It cannot, however, use the run action while climbing.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spider Climb\" level=\"5\"><p><h5>Spider Climb</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject can climb and travel on vertical surfaces or even traverse ceilings as well as a spider does. The affected creature must have its hands free to climb in this manner. The subject gains a climb speed of 20 feet; furthermore, it need not make Climb checks to traverse a vertical or horizontal surface (even upside down). A <i>spider climbing</i> creature retains its Dexterity bonus to Armor Class (if any) while climbing, and opponents get no special bonus to their attacks against it. It cannot, however, use the run action while climbing.</p><p><i>Material Component:</i> A drop of bitumen and a live spider, both of which must be eaten by the subject.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (596,'Spike Growth','spike growth','Transmutation',NULL,NULL,NULL,'Druid 3, Ranger 2','V, S, DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'One 20-ft. square/level',NULL,'1 hour/level (D)','Reflex partial','Yes','Creatures in area take 1d4 damage, may be slowed.',NULL,NULL,NULL,NULL,'\n      <p>Any ground-covering vegetation in the spell\'s area becomes very hard and sharply pointed without changing its appearance.</p>\n      <p>In areas of bare earth, roots and rootlets act in the same way. Typically, <i>Spike growth</i> can be cast in any outdoor setting except open water, ice, heavy snow, sandy desert, or bare stone. Any creature moving on foot into or through the spell\'s area takes 1d4 points of piercing damage for each 5 feet of movement through the spiked area.</p>\n      <p>Any creature that takes damage from this spell must also succeed on a Reflex save or suffer injuries to its feet and legs that slow its land speed by one-half. This speed penalty lasts for 24 hours or until the injured creature receives a <i>cure</i> spell (which also restores lost hit points). Another character can remove the penalty by taking 10 minutes to dress the injuries and succeeding on a Heal check against the spell\'s save DC.</p>\n      <p><i>Spike growth</i> can\'t be disabled with the Disable Device skill.</p>\n      <p><i>Note:</i> Magic traps such as <i>Spike growth</i> are hard to detect. A rogue (only) can use the Search skill to find a <i>spike growth</i>. The DC is 25 + spell level, or DC 28 for <i>Spike growth</i> (or DC 27 for <i>Spike growth</i> cast by a ranger).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spike Growth\" level=\"5\"><p><h5>Spike Growth</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 3, Ranger 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>One 20-ft. square/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Any ground-covering vegetation in the spell\'s area becomes very hard and sharply pointed without changing its appearance.</p><p>In areas of bare earth, roots and rootlets act in the same way. Typically, <i>Spike growth</i> can be cast in any outdoor setting except open water, ice, heavy snow, sandy desert, or bare stone. Any creature moving on foot into or through the spell\'s area takes 1d4 points of piercing damage for each 5 feet of movement through the spiked area.</p><p>Any creature that takes damage from this spell must also succeed on a Reflex save or suffer injuries to its feet and legs that slow its land speed by one-half. This speed penalty lasts for 24 hours or until the injured creature receives a <i>cure</i> spell (which also restores lost hit points). Another character can remove the penalty by taking 10 minutes to dress the injuries and succeeding on a Heal check against the spell\'s save DC.</p><p><i>Spike growth</i> can\'t be disabled with the Disable Device skill.</p><p><i>Note:</i> Magic traps such as <i>Spike growth</i> are hard to detect. A rogue (only) can use the Search skill to find a <i>spike growth</i>. The DC is 25 + spell level, or DC 28 for <i>Spike growth</i> (or DC 27 for <i>Spike growth</i> cast by a ranger).</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (597,'Spike Stones','spike stones','Transmutation',NULL,'Earth',NULL,'Druid 4, Earth 4','V, S, DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'One 20-ft. square/level',NULL,'1 hour/level (D)','Reflex partial','Yes','Creatures in area take 1d8 damage, may be slowed.',NULL,NULL,NULL,NULL,'\n      <p>Rocky ground, stone floors, and similar surfaces shape themselves into long, sharp points that blend into the background.</p>\n      <p><i>spike stones</i> impede progress through an area and deal damage. Any creature moving on foot into or through the spell\'s area moves at half speed.</p>\n      <p>In addition, each creature moving through the area takes 1d8 points of piercing damage for each 5 feet of movement through the spiked area.</p>\n      <p>Any creature that takes damage from this spell must also succeed on a Reflex save to avoid injuries to its feet and legs. A failed save causes the creature\'s speed to be reduced to half normal for 24 hours or until the injured creature receives a <i>cure</i> spell (which also restores lost hit points). Another character can remove the penalty by taking 10 minutes to dress the injuries and succeeding on a Heal check against the spell\'s save DC.</p>\n      <p><i>spike stones</i> is a magic trap that can\'t be disabled with the Disable Device skill.</p>\n      <p><i>Note:</i> Magic traps such as <i>spike stones</i> are hard to detect. A rogue (only) can use the Search skill to find <i>spike stones</i>. The DC is 25 + spell level, or DC 29 for <i>spike stones</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spike Stones\" level=\"5\"><p><h5>Spike Stones</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 4, Earth 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>One 20-ft. square/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Rocky ground, stone floors, and similar surfaces shape themselves into long, sharp points that blend into the background.</p><p><i>spike stones</i> impede progress through an area and deal damage. Any creature moving on foot into or through the spell\'s area moves at half speed.</p><p>In addition, each creature moving through the area takes 1d8 points of piercing damage for each 5 feet of movement through the spiked area.</p><p>Any creature that takes damage from this spell must also succeed on a Reflex save to avoid injuries to its feet and legs. A failed save causes the creature\'s speed to be reduced to half normal for 24 hours or until the injured creature receives a <i>cure</i> spell (which also restores lost hit points). Another character can remove the penalty by taking 10 minutes to dress the injuries and succeeding on a Heal check against the spell\'s save DC.</p><p><i>spike stones</i> is a magic trap that can\'t be disabled with the Disable Device skill.</p><p><i>Note:</i> Magic traps such as <i>spike stones</i> are hard to detect. A rogue (only) can use the Search skill to find <i>spike stones</i>. The DC is 25 + spell level, or DC 29 for <i>spike stones</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (598,'Spiritual Weapon','spiritual weapon','Evocation',NULL,'Force',NULL,'Cleric 2, War 2','V, S, DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Magic weapon of force','1 round/level (D)','None','Yes','Magical weapon attacks on its own.',NULL,NULL,NULL,NULL,'\n      <p>A weapon made of pure force springs into existence and attacks opponents at a distance, as you direct it, dealing 1d8 force damage per hit, +1 point per three caster levels (maximum +5 at 15th level). The weapon takes the shape of a weapon favored by your deity or a weapon with some spiritual significance or symbolism to you (see below) and has the same threat range and critical multipliers as a real weapon of its form. It strikes the opponent you designate, starting with one attack in the round the spell is cast and continuing each round thereafter on your turn. It uses your base attack bonus (possibly allowing it multiple attacks per round in subsequent rounds) plus your Wisdom modifier as its attack bonus. It strikes as a spell, not as a weapon, so, for example, it can damage creatures that have damage reduction. As a force effect, it can strike incorporeal creatures without the normal miss chance associated with incorporeality. The weapon always strikes from your direction. It does not get a flanking bonus or help a combatant get one. Your feats or combat actions do not affect the weapon. If the weapon goes beyond the spell range, if it goes out of your sight, or if you are not directing it, the weapon returns to you and hovers.</p>\n      <p>Each round after the first, you can use a move action to redirect the weapon to a new target. If you do not, the weapon continues to attack the previous round\'s target. On any round that the weapon switches targets, it gets one attack. Subsequent rounds of attacking that target allow the weapon to make multiple attacks if your base attack bonus would allow it to. Even if the <i>spiritual weapon</i> is a ranged weapon, use the spell\'s range, not the weapon\'s normal range increment, and switching targets still is a move action.</p>\n      <p>A <i>spiritual weapon</i> cannot be attacked or harmed by physical attacks, but <i>dispel magic</i>, <i>disintegrate</i>, a <i>sphere of annihilation</i>, or a <i>rod of cancellation</i> affects it. A <i>spiritual weapon</i>\'s AC against touch attacks is 12 (10 + size bonus for Tiny object).</p>\n      <p>If an attacked creature has spell resistance, you make a caster level check (1d20 + caster level) against that spell resistance the first time the <i>spiritual weapon</i> strikes it. If the weapon is successfully resisted, the spell is dispelled. If not, the weapon has its normal full effect on that creature for the duration of the spell.</p>\n      <p>The weapon that you get is often a force replica of your deity\'s own personal weapon. A cleric without a deity gets a weapon based on his alignment. A neutral cleric without a deity can create a <i>spiritual weapon</i> of any alignment, provided he is acting at least generally in accord with that alignment at the time. The weapons associated with each alignment are as follows.</p>\n      <div topic=\"Chaos: Battleaxe\" level=\"8\"><p><i>Chaos:</i> Battleaxe</p>\n</div>\n      <div topic=\"Evil: Light Flail\" level=\"8\"><p><i>Evil:</i> Light flail</p>\n</div>\n      <div topic=\"Good: Warhammer\" level=\"8\"><p><i>Good:</i> Warhammer</p><p><i>Law:</i> Longsword,</p><p/>\n</div>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Spiritual Weapon\" level=\"5\"><p><h5>Spiritual Weapon</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, War 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Magic weapon of force<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A weapon made of pure force springs into existence and attacks opponents at a distance, as you direct it, dealing 1d8 force damage per hit, +1 point per three caster levels (maximum +5 at 15th level). The weapon takes the shape of a weapon favored by your deity or a weapon with some spiritual significance or symbolism to you (see below) and has the same threat range and critical multipliers as a real weapon of its form. It strikes the opponent you designate, starting with one attack in the round the spell is cast and continuing each round thereafter on your turn. It uses your base attack bonus (possibly allowing it multiple attacks per round in subsequent rounds) plus your Wisdom modifier as its attack bonus. It strikes as a spell, not as a weapon, so, for example, it can damage creatures that have damage reduction. As a force effect, it can strike incorporeal creatures without the normal miss chance associated with incorporeality. The weapon always strikes from your direction. It does not get a flanking bonus or help a combatant get one. Your feats or combat actions do not affect the weapon. If the weapon goes beyond the spell range, if it goes out of your sight, or if you are not directing it, the weapon returns to you and hovers.</p><p>Each round after the first, you can use a move action to redirect the weapon to a new target. If you do not, the weapon continues to attack the previous round\'s target. On any round that the weapon switches targets, it gets one attack. Subsequent rounds of attacking that target allow the weapon to make multiple attacks if your base attack bonus would allow it to. Even if the <i>spiritual weapon</i> is a ranged weapon, use the spell\'s range, not the weapon\'s normal range increment, and switching targets still is a move action.</p><p>A <i>spiritual weapon</i> cannot be attacked or harmed by physical attacks, but <i>dispel magic</i>, <i>disintegrate</i>, a <i>sphere of annihilation</i>, or a <i>rod of cancellation</i> affects it. A <i>spiritual weapon</i>\'s AC against touch attacks is 12 (10 + size bonus for Tiny object).</p><p>If an attacked creature has spell resistance, you make a caster level check (1d20 + caster level) against that spell resistance the first time the <i>spiritual weapon</i> strikes it. If the weapon is successfully resisted, the spell is dispelled. If not, the weapon has its normal full effect on that creature for the duration of the spell.</p><p>The weapon that you get is often a force replica of your deity\'s own personal weapon. A cleric without a deity gets a weapon based on his alignment. A neutral cleric without a deity can create a <i>spiritual weapon</i> of any alignment, provided he is acting at least generally in accord with that alignment at the time. The weapons associated with each alignment are as follows.</p><div topic=\"Chaos: Battleaxe\" level=\"8\"><p><i>Chaos:</i> Battleaxe</p>\n</div><div topic=\"Evil: Light Flail\" level=\"8\"><p><i>Evil:</i> Light flail</p>\n</div><div topic=\"Good: Warhammer\" level=\"8\"><p><i>Good:</i> Warhammer</p><p><i>Law:</i> Longsword,</p><p/>\n</div>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (599,'Statue','statue','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 7','V, S, M','1 round','Touch','Creature touched',NULL,NULL,'1 hour/level (D)','Will negates (harmless)','Yes (harmless)','Subject can become a statue at will.',NULL,'Lime, sand, and a drop of water stirred by an iron bar, such as a nail or spike.',NULL,NULL,'\n      <p>A <i>statue</i> spell turns the subject to solid stone, along with any garments and equipment worn or carried. In statue form, the subject gains hardness 8. The subject retains its own hit points.</p>\n      <p>The subject can see, hear, and smell normally, but it does not need to eat or breathe. Feeling is limited to those sensations that can affect the granite-hard substance of the individual\'s body. Chipping is equal to a mere scratch, but breaking off one of the statue\'s arms constitutes serious damage.</p>\n      <p>The subject of a <i>statue</i> spell can return to its normal state, act, and then return instantly to the statue state (a free action) if it so desires, as long as the spell duration is in effect.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Statue\" level=\"5\"><p><h5>Statue</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>A <i>statue</i> spell turns the subject to solid stone, along with any garments and equipment worn or carried. In statue form, the subject gains hardness 8. The subject retains its own hit points.</p><p>The subject can see, hear, and smell normally, but it does not need to eat or breathe. Feeling is limited to those sensations that can affect the granite-hard substance of the individual\'s body. Chipping is equal to a mere scratch, but breaking off one of the statue\'s arms constitutes serious damage.</p><p>The subject of a <i>statue</i> spell can return to its normal state, act, and then return instantly to the statue state (a free action) if it so desires, as long as the spell duration is in effect.</p><p><i>Material Component:</i> Lime, sand, and a drop of water stirred by an iron bar, such as a nail or spike.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (600,'Status','status','Divination',NULL,NULL,NULL,'Cleric 2','V, S','1 standard action','Touch','One living creature touched per three levels',NULL,NULL,'1 hour/level','Will negates (harmless)','Yes (harmless)','Monitors condition, position of allies.',NULL,NULL,NULL,NULL,'\n      <p>When you need to keep track of comrades who may get separated, <i>status</i> allows you to mentally monitor their relative positions and general condition. You are aware of direction and distance to the creatures and any conditions affecting them: unharmed, wounded, disabled, staggered, unconscious, dying, nauseated, panicked, stunned, poisoned, diseased, <i>confused</i>,  or the like. Once the spell has been cast upon the subjects, the distance between them and the caster does not affect the spell as long as they are on the same plane of existence. If a subject leaves the plane, or if it dies, the spell ceases to function for it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Status\" level=\"5\"><p><h5>Status</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One living creature touched per three levels<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>When you need to keep track of comrades who may get separated, <i>status</i> allows you to mentally monitor their relative positions and general condition. You are aware of direction and distance to the creatures and any conditions affecting them: unharmed, wounded, disabled, staggered, unconscious, dying, nauseated, panicked, stunned, poisoned, diseased, <i>confused</i>,  or the like. Once the spell has been cast upon the subjects, the distance between them and the caster does not affect the spell as long as they are on the same plane of existence. If a subject leaves the plane, or if it dies, the spell ceases to function for it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (601,'Stinking Cloud','stinking cloud','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 3','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Cloud spreads in 20-ft. radius, 20 ft. high','1 round/level','Fortitude negates; see text','No','Nauseating vapors, 1 round/level.',NULL,'A rotten egg or several skunk cabbage leaves.',NULL,NULL,'\n      <p><i>stinking cloud</i> creates a bank of fog like that created by <i>fog cloud</i>, except that the vapors are nauseating. Living creatures in the cloud become nauseated. This condition lasts as long as the creature is in the cloud and for 1d4+1 rounds after it leaves. (Roll separately for each nauseated character.) Any creature that succeeds on its save but remains in the cloud must continue to save each round on your turn.</p>\n      <p><i>stinking cloud</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>stinking cloud</i> dispersed by wind reforms in 10 minutes.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Stinking Cloud\" level=\"5\"><p><h5>Stinking Cloud</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Cloud spreads in 20-ft. radius, 20 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p><i>stinking cloud</i> creates a bank of fog like that created by <i>fog cloud</i>, except that the vapors are nauseating. Living creatures in the cloud become nauseated. This condition lasts as long as the creature is in the cloud and for 1d4+1 rounds after it leaves. (Roll separately for each nauseated character.) Any creature that succeeds on its save but remains in the cloud must continue to save each round on your turn.</p><p><i>stinking cloud</i> can be made permanent with a <i>permanency</i> spell. A permanent <i>stinking cloud</i> dispersed by wind reforms in 10 minutes.</p><p><i>Material Component:</i> A rotten egg or several skunk cabbage leaves.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (602,'Stone Shape','stone shape','Transmutation',NULL,'Earth',NULL,'Cleric 3, Druid 3, Earth 3, Sorcerer/Wizard 4','V, S, M/DF','1 standard action','Touch','Stone or stone object touched, up to 10 cu. ft. + 1 cu. ft./level',NULL,NULL,'Instantaneous','None','No','Sculpts stone into any shape.',NULL,NULL,'Soft clay, which must be worked into roughly the desired shape of the stone object and then touched to the stone while the verbal component is uttered.',NULL,'\n      <p>You can form an existing piece of stone into any shape that suits your purpose. While it\'s possible to make crude coffers, doors, and so forth with <i>stone shape</i>,  fine detail isn\'t possible. There is a 30% chance that any shape including moving parts simply doesn\'t work.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Stone Shape\" level=\"5\"><p><h5>Stone Shape</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Earth]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Druid 3, Earth 3, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Stone or stone object touched, up to 10 cu. ft. + 1 cu. ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can form an existing piece of stone into any shape that suits your purpose. While it\'s possible to make crude coffers, doors, and so forth with <i>stone shape</i>,  fine detail isn\'t possible. There is a 30% chance that any shape including moving parts simply doesn\'t work.</p><p><i>Arcane Material Component:</i> Soft clay, which must be worked into roughly the desired shape of the stone object and then touched to the stone while the verbal component is uttered.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (603,'Stoneskin','stoneskin','Abjuration',NULL,NULL,NULL,'Druid 5, Earth 6, Sorcerer/Wizard 4, Strength 6','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'10 min./level or until discharged','Will negates (harmless)','Yes (harmless)','Ignore 10 points of damage per attack.',NULL,'Granite and 250 gp worth of diamond dust sprinkled on the target\'s skin.',NULL,NULL,'\n      <p>The warded creature gains resistance to blows, cuts, stabs, and slashes. The subject gains damage reduction 10/adamantine. (It ignores the first 10 points of damage each time it takes damage from a weapon, though an adamantine weapon bypasses the reduction.) Once the spell has prevented a total of 10 points of damage per caster level (maximum 150 points), it is discharged.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Stoneskin\" level=\"5\"><p><h5>Stoneskin</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Earth 6, Sorcerer/Wizard 4, Strength 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level or until discharged<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The warded creature gains resistance to blows, cuts, stabs, and slashes. The subject gains damage reduction 10/adamantine. (It ignores the first 10 points of damage each time it takes damage from a weapon, though an adamantine weapon bypasses the reduction.) Once the spell has prevented a total of 10 points of damage per caster level (maximum 150 points), it is discharged.</p><p><i>Material Component:</i> Granite and 250 gp worth of diamond dust sprinkled on the target\'s skin.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (604,'Stone Tell','stone tell','Divination',NULL,NULL,NULL,'Druid 6','V, S, DF','10 minutes','Personal','You',NULL,NULL,'1 min./level',NULL,NULL,'Talk to natural or worked stone.',NULL,NULL,NULL,NULL,'\n      <p>You gain the ability to speak with stones, which relate to you who or what has touched them as well as revealing what is covered or concealed behind or under them. The stones relate complete descriptions if asked. A stone\'s perspective, perception, and knowledge may prevent the stone from providing the details you are looking for.</p>\n      <p>You can speak with natural or worked stone.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Stone Tell\" level=\"5\"><p><h5>Stone Tell</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr></table><p>You gain the ability to speak with stones, which relate to you who or what has touched them as well as revealing what is covered or concealed behind or under them. The stones relate complete descriptions if asked. A stone\'s perspective, perception, and knowledge may prevent the stone from providing the details you are looking for.</p><p>You can speak with natural or worked stone.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (605,'Stone to Flesh','stone to flesh','Transmutation',NULL,NULL,NULL,'Sorcerer/Wizard 6','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)','One petrified creature or a cylinder of stone from 1 ft. to 3 ft. in diameter and up to 10 ft. long',NULL,NULL,'Instantaneous','Fortitude negates (object); see text','Yes','Restores petrified creature.',NULL,'A pinch of earth and a drop of blood.',NULL,NULL,'\n      <p>This spell restores a petrified creature to its normal state, restoring life and goods. The creature must make a DC 15 Fortitude save to survive the process. Any petrified creature, regardless of size, can be restored.</p>\n      <p>The spell also can convert a mass of stone into a fleshy substance. Such flesh is inert and lacking a vital life force unless a life force or magical energy is available. (For example, this spell would turn a stone golem into a flesh golem, but an ordinary statue would become a corpse.) You can affect an object that fits within a cylinder from 1 foot to 3 feet in diameter and up to 10 feet long or a cylinder of up to those dimensions in a larger mass of stone.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Stone to Flesh\" level=\"5\"><p><h5>Stone to Flesh</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One petrified creature or a cylinder of stone from 1 ft. to 3 ft. in diameter and up to 10 ft. long<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (object); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell restores a petrified creature to its normal state, restoring life and goods. The creature must make a DC 15 Fortitude save to survive the process. Any petrified creature, regardless of size, can be restored.</p><p>The spell also can convert a mass of stone into a fleshy substance. Such flesh is inert and lacking a vital life force unless a life force or magical energy is available. (For example, this spell would turn a stone golem into a flesh golem, but an ordinary statue would become a corpse.) You can affect an object that fits within a cylinder from 1 foot to 3 feet in diameter and up to 10 feet long or a cylinder of up to those dimensions in a larger mass of stone.</p><p><i>Material Component:</i> A pinch of earth and a drop of blood.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (606,'Storm of Vengeance','storm of vengeance','Conjuration','Summoning',NULL,NULL,'Druid 9, Cleric 9','V, S','1 round','Long (400 ft. + 40 ft./level)',NULL,NULL,'360-ft. -radius storm cloud','Concentration (maximum 10 rounds) (D)','See text','Yes','Storm rains acid, lightning, and hail.',NULL,NULL,NULL,NULL,'\n      <p>This spell creates an enormous black storm cloud. Lightning and crashing claps of thunder appear within the storm. Each creature beneath the cloud must succeed on a Fortitude save or be deafened for 1d4x10 minutes.</p>\n      <p>If you do not maintain concentration on the spell after casting it, the spell ends.  If you continue to concentrate, the spell generates additional effects in each following round, as noted below. Each effect occurs during your turn.</p>\n      <p><i>2nd Round:</i> Acid rains down in the area, dealing 1d6 points of acid damage (no save).</p>\n      <p><i>3rd Round:</i> You call six bolts of lightning down from the cloud. You decide where the bolts strike. No two bolts may be directed at the same target. Each bolt deals 10d6 points of electricity damage. A creature struck can attempt a Reflex save for half damage.</p>\n      <p><i>4th Round:</i> Hailstones rain down in the area, dealing 5d6 points of bludgeoning damage (no save).</p>\n      <p><i>5th through 10th Rounds:</i> Violent rain and wind gusts reduce visibility. The rain obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target). Speed is reduced by three-quarters.</p>\n      <p>Ranged attacks within the area of the storm are impossible. Spells cast within the area are disrupted unless the caster succeeds on a Concentration check against a DC equal to the <i>storm of vengeance</i>\'s save DC + the level of the spell the caster is trying to cast.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Storm of Vengeance\" level=\"5\"><p><h5>Storm of Vengeance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 9, Cleric 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>360-ft. -radius storm cloud<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration (maximum 10 rounds) (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell creates an enormous black storm cloud. Lightning and crashing claps of thunder appear within the storm. Each creature beneath the cloud must succeed on a Fortitude save or be deafened for 1d4x10 minutes.</p><p>If you do not maintain concentration on the spell after casting it, the spell ends.  If you continue to concentrate, the spell generates additional effects in each following round, as noted below. Each effect occurs during your turn.</p><p><i>2nd Round:</i> Acid rains down in the area, dealing 1d6 points of acid damage (no save).</p><p><i>3rd Round:</i> You call six bolts of lightning down from the cloud. You decide where the bolts strike. No two bolts may be directed at the same target. Each bolt deals 10d6 points of electricity damage. A creature struck can attempt a Reflex save for half damage.</p><p><i>4th Round:</i> Hailstones rain down in the area, dealing 5d6 points of bludgeoning damage (no save).</p><p><i>5th through 10th Rounds:</i> Violent rain and wind gusts reduce visibility. The rain obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target). Speed is reduced by three-quarters.</p><p>Ranged attacks within the area of the storm are impossible. Spells cast within the area are disrupted unless the caster succeeds on a Concentration check against a DC equal to the <i>storm of vengeance</i>\'s save DC + the level of the spell the caster is trying to cast.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (607,'Suggestion','suggestion','Enchantment','Compulsion','Language-Dependent, Mind-Affecting',NULL,'Bard 2, Sorcerer/Wizard 3','V, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'1 hour/level or until completed','Will negates','Yes','Compels subject to follow stated course of action.',NULL,'A snake\'s tongue and either a bit of honeycomb or a drop of sweet oil.',NULL,NULL,'\n      <p>You influence the actions of the target creature by suggesting a course of activity (limited to a sentence or two). The <i>suggestion</i> must be worded in such a manner as to make the activity sound reasonable. Asking the creature to do some obviously harmful act automatically negates the effect of the spell.</p>\n      <p>The suggested course of activity can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do. You can instead specify conditions that will trigger a special activity during the duration. If the condition is not met before the spell duration expires, the activity is not performed.</p>\n      <p>A very reasonable <i>suggestion</i> causes the save to be made with a penalty (such as -1 or -2).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Suggestion\" level=\"5\"><p><h5>Suggestion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level or until completed<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You influence the actions of the target creature by suggesting a course of activity (limited to a sentence or two). The <i>suggestion</i> must be worded in such a manner as to make the activity sound reasonable. Asking the creature to do some obviously harmful act automatically negates the effect of the spell.</p><p>The suggested course of activity can continue for the entire duration. If the suggested activity can be completed in a shorter time, the spell ends when the subject finishes what it was asked to do. You can instead specify conditions that will trigger a special activity during the duration. If the condition is not met before the spell duration expires, the activity is not performed.</p><p>A very reasonable <i>suggestion</i> causes the save to be made with a penalty (such as -1 or -2).</p><p><i>Material Component:</i> A snake\'s tongue and either a bit of honeycomb or a drop of sweet oil.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (608,'Suggestion, Mass','mass suggestion','Enchantment','Compulsion','Language-Dependent, Mind-Affecting',NULL,'Bard 5, Sorcerer/Wizard 6','V, M','1 standard action','Medium (100 ft. + 10 ft./level)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 hour/level or until completed','Will negates','Yes','As suggestion, plus one subject/level.',NULL,'A snake\'s tongue and either a bit of honeycomb or a drop of sweet oil.',NULL,NULL,'\n      <p>This spell functions like <i>suggestion</i>, except that it can affect more creatures. The same <i>suggestion</i> applies to all these creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Suggestion, Mass\" level=\"5\"><p><h5>Suggestion, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>suggestion</i>, except that it can affect more creatures. The same <i>suggestion</i> applies to all these creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (609,'Summon Instrument','summon instrument','Conjuration','Summoning',NULL,NULL,'Bard 0','V, S','1 round','0 ft.',NULL,NULL,'One summoned handheld musical instrument','1 min./level (D)','None','No','Summons one instrument of the caster\'s choice.',NULL,NULL,NULL,NULL,'\n      <p>This spell summons one handheld musical instrument of your choice. This instrument appears in your hands or at your feet (your choice). The instrument is typical for its type. Only one instrument appears per casting, and it will play only for you. You can\'t summon an instrument too large to be held in two hands.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Instrument\" level=\"5\"><p><h5>Summon Instrument</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One summoned handheld musical instrument<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell summons one handheld musical instrument of your choice. This instrument appears in your hands or at your feet (your choice). The instrument is typical for its type. Only one instrument appears per casting, and it will play only for you. You can\'t summon an instrument too large to be held in two hands.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (610,'Summon Monster I','summon monster I','Conjuration','Summoning','see text',NULL,'Bard 1, Cleric 1, Sorcerer/Wizard 1','V, S, F/DF','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One summoned creature','1 round/level (D)','None','No','Calls extraplanar creature to fight for you.',NULL,NULL,NULL,NULL,'\n      <p>This spell summons an extraplanar creature (typically an outsider, elemental, or magical beast native to another plane). It appears where you designate and acts immediately, on your turn. It attacks your opponents to the best of its ability. If you can communicate with the creature, you can direct it not to attack, to attack particular enemies, or to perform other actions.</p>\n      <p>The spell conjures one of the creatures from the 1st-level list on the accompanying Summon Monster table. You choose which kind of creature to summon, and you can change that choice each time you cast the spell.</p>\n      <p>A summoned monster cannot summon or otherwise conjure another creature, nor can it use any teleportation or planar travel abilities. Creatures cannot be summoned into an environment that cannot support them.</p>\n      <p>When you use a summoning spell to summon an air, chaotic, earth, evil, fire, good, lawful, or water creature, it is a spell of that type.</p>\n      <p/>\n    ',NULL,'A tiny bag and a small (not necessarily lit) candle.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Monster I\" level=\"5\"><p><h5>Summon Monster I</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [see text]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Cleric 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One summoned creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell summons an extraplanar creature (typically an outsider, elemental, or magical beast native to another plane). It appears where you designate and acts immediately, on your turn. It attacks your opponents to the best of its ability. If you can communicate with the creature, you can direct it not to attack, to attack particular enemies, or to perform other actions.</p><p>The spell conjures one of the creatures from the 1st-level list on the accompanying Summon Monster table. You choose which kind of creature to summon, and you can change that choice each time you cast the spell.</p><p>A summoned monster cannot summon or otherwise conjure another creature, nor can it use any teleportation or planar travel abilities. Creatures cannot be summoned into an environment that cannot support them.</p><p>When you use a summoning spell to summon an air, chaotic, earth, evil, fire, good, lawful, or water creature, it is a spell of that type.</p><p><i>Arcane Focus:</i> A tiny bag and a small (not necessarily lit) candle.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (611,'Summon Monster II','summon monster II','Conjuration','Summoning','see text for summon monster I',NULL,'Bard 2, Cleric 2, Sorcerer/Wizard 2','V, S, F/DF','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two of which can be more than 30 ft. apart','1 round/level (D)','None','No','Calls extraplanar creature to fight for you.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 2nd-level list or 1d3 creatures of the same kind from the 1st-level list.</p>\n      <p/>\n    ',NULL,'A tiny bag and a small (not necessarily lit) candle.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Monster II\" level=\"5\"><p><h5>Summon Monster II</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [see text for summon monster I]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One or more summoned creatures, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 2nd-level list or 1d3 creatures of the same kind from the 1st-level list.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (612,'Summon Monster III','summon monster III','Conjuration','Summoning','see text for summon monster I',NULL,'Bard 3, Cleric 3, Sorcerer/Wizard 3','V, S, F/DF','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two of which can be more than 30 ft. apart','1 round/level (D)','None','No','Calls extraplanar creature to fight for you.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 3rd-level list, 1d3 creatures of the same kind from the 2nd-level list, or 1d4+1 creatures of the same kind from the 1st-level list.</p>\n      <p/>\n    ',NULL,'A tiny bag and a small (not necessarily lit) candle.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Monster III\" level=\"5\"><p><h5>Summon Monster III</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [see text for summon monster I]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Cleric 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One or more summoned creatures, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 3rd-level list, 1d3 creatures of the same kind from the 2nd-level list, or 1d4+1 creatures of the same kind from the 1st-level list.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
INSERT INTO spell VALUES (613,'Summon Monster IV','summon monster IV','Conjuration','Summoning','see text for summon monster I',NULL,'Bard 4, Cleric 4, Sorcerer/Wizard 4','V, S, F/DF','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two of which can be more than 30 ft. apart','1 round/level (D)','None','No','Calls extraplanar creature to fight for you.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 4th-level list, 1d3 creatures of the same kind from the 3rd-level list, or 1d4+1 creatures of the same kind from a lower-level list.</p>\n      <p/>\n    ',NULL,'A tiny bag and a small (not necessarily lit) candle.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Summon Monster IV\" level=\"5\"><p><h5>Summon Monster IV</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning) [see text for summon monster I]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Cleric 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One or more summoned creatures, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>summon monster I</i>,  except that you can summon one creature from the 4th-level list, 1d3 creatures of the same kind from the 3rd-level list, or 1d4+1 creatures of the same kind from a lower-level list.</p><p/>\n</div>\n    ','SRD 3.5 SpellsS');
